(window.GIM_TS=window.GIM_TS||{})["Eruvin.7"]={"from":168,"a":[["\u0003פנו מקום\u0004 חשוב יותר \u0003לבן מאתים מנה. אמר לפניו ר' ישמעאל בר' יוסי: רבי, אביו של זה,\u0004 בונייס, \u0003יש לו אלף ספינות בים וכנגדן אלף עיירות ביבשה.\u0004 ועשיר מופלג הוא, וצריך לתת לו מקום מכובד יותר. \u0003אמר לו: לכשתגיע אצל אביו\u0004 של זה \u0003אמור לו: אל תשגרהו\u0004 (תשלח אותו) \u0003בכלים\u0004 (בלבושים) \u0003הללו לפני,\u0004 אלא ילבש לפי עושרו וכבודו, ואז יכבדוהו כראוי לו.","ומעירים בביאור הדברים, \u0003רבי מכבד\u0004 היה \u0003עשירים\u0004 ונותן להם מקום נכבד בזכות עושרם. וכן \u0003ר' עקיבא מכבד\u0004 היה \u0003עשירים.\u0004 ומסבירים שטעם הדבר הוא כפי ש\u0003דרש רבא בר מרי\u0004 על הכתוב: \u0003\"ישב עולם לפני אלהים חסד ואמת מן ינצרהו\"\u0004 (תהלים סא, ח) — \u0003אימתי ישב עולם לפני אלהים? בזמן שחסד ואמת מן ינצרהו,\u0004 שיהיו אנשים עשירים המסוגלים לתת מנות מזון (\"מן\") וחסד לאחרים. ומשום כך ראוי לכבד את העשירים הגומלים חסד.","\u0003רבה בר בר חנה אמר:\u0004 כיצד היא תפיסת יד, \u0003כגון\u0004 שיש לו לבעל הבית \u0003יתד של מחרישה\u0004 בבית הדייר. וכיון שאסור לדייר לטלטל יתד זו מביתו ביום השבת, משום איסור מוקצה, נמצא שיש לבעל הבית תפיסת מקום קבועה בבית זה.","\u0003אמר רב נחמן, תנא דבי\u0004 \u0005[שנה\u0006 התנא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 בברייתא זו: היה לבעל הבית אצל הדייר \u0003דבר הניטל בשבת — אוסר,\u0004 שאיננו נחשב תפיסת יד לבעל הבית, ודירה זו אוסרת. אבל \u0003דבר שאינו ניטל בשבת — אינו אוסר.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 אם \u0003יש לו\u0004 לבעל הבית אצל הדייר \u0003טבל\u0004 (תבואה שלא עושרה) ואסור לטלטלה בשבת, או ש\u0003יש לו עששית\u0004 (גושי מתכת או זכוכית), וכיוצא בזה \u0003כל דבר שאינו ניטל בשבת\u0004 — הדייר \u0003אינו אוסר\u0004","\u0003המניח ביתו\u0004 שבתוך חצר משותפת \u0003והלך לשבות בעיר אחרת, אחד גוי ואחד ישראל — הרי זה אוסר\u0004 כאילו היה מצוי בביתו, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: אינו אוסר,\u0004 שדירה ריקה אינה אוסרת.","\u0003ר' יוסי אומר: גוי — אוסר, ישראל — אינו אוסר.\u0004 וטעמו של דבר, \u0003שאין דרך ישראל לבא בשבת.\u0004 וכיון שלא יחזור, דירתו הריקה אינה אוסרת. אבל הגוי כיון שיתכן שיבוא בחזרה במשך יום השבת, אין עקירתו מביתו חשובה כעקירה ואוסר.","\u0003ר' שמעון אומר: אפילו\u0004 ישראל שרק \u0003הניח ביתו והלך לשבות אצל בתו באותה העיר — אינו אוסר,\u0004 שאף שיכול לכאורה לחזור בכל עת לביתו, אנו מניחים \u0003שכבר הסיע\u0004 (הסיח) \u0003מלבו\u0004 לחזור אל הבית, וקבע דירתו לשבת במקום אחר.","\u0003אמר רב: הלכה כר' שמעון\u0004 לענין זה. ומעירים: \u0003ודוקא\u0004 שהלך לבית \u0003בתו, אבל\u0004 הלך לבית \u0003בנו — לא,\u0004 אין הוא בטוח שיוכל להתארח שם, שמא לא תרצה כלתו בכך, ויצטרך לשוב לביתו. \u0003דאמרי אינשי\u0004 \u0005[שאומרים האנשים]\u0006 בפתגם מקובל: \u0003נבח בך כלבא\u0004 \u0005[כלב] —\u0006 \u0003עול\u0004 \u0005[הכנס],\u0006 \u0003נבח בך גורייתא\u0004 \u0005[נבחה בך כלבה] —\u0006 \u0003פוק\u0004 \u0005[צא],\u0006 כלומר קשה התנגדותה של נקבה, כגון כלתו, שבודאי לא יעמוד בנו כנגדה, מהתנגדותו של זכר, כגון חתנו.","\u0003בור שבין שתי חצירות\u0004 שחלק ממנו בתוך כל חצר — \u0003אין ממלאין ממנו בשבת,\u0004 שלא יהא אחד ממלא מרשות חבירו, \u0003אלא אם כן עשו לו מחיצה גבוהה עשרה טפחים\u0004 להבדיל בין רשות לרשות. \u0003בין\u0004 שהיתה \u0003מלמטה\u0004 בתוך מי הבור, \u0003בין מתוך אוגנו\u0004 חללו של הבור למעלה מן המים.","\u0003רבן שמעון בן גמליאל אומר:\u0004 מחלוקת קדמונים היתה בדבר זה ש\u0003בית שמאי אומרים:\u0004 מחיצה המתרת צריך שתהא \u0003מלמטה, ובית הלל אומרים: מלמעלה. אמר ר' יהודה: לא תהא מחיצה גדולה מן הכותל שביניהם,\u0004 ודי בכותל שבין שתי החצירות אם הוא עובר מעל לבור כדי לשמש הפסק ביניהן, ואין צורך לעשות מחיצה בחללו של הבור.","\u0003אמר רב הונא:\u0004 מה ששנינו בשם בית שמאי \u0003למטה\u0004 — משמעו \u0003למטה ממש\u0004 סמוך למים, \u0003למעלה\u0004 שאמרו בית הלל — פירושו \u0003למעלה ממש\u0004 גבוה מעל למים, \u0003וזה וזה\u0004 בתוך חלל ה\u0003בור. ו\u0004אילו \u0003רב יהודה אמר: למטה\u0004 פירושו — \u0003למטה מן המים,\u0004 שחלק מן המחיצה מצוי בתוך המים. \u0003למעלה\u0004 — משמעו \u0003למעלה מן המים\u0004 בלי שהמחיצה נוגעת במים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנן לאביי: הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה \"למטה — למטה מן המים\",\u0004 יש מקום לשאול: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003למטה\u0004 בתוך הבור סמוך לפני המים \u0003ממש\u0004 ש\u0003לא,\u0004 משום שהוא חושש \u0003דעריבי מיא\u0004 \u0005[שמתערבים המים]\u0006 מתחת למחיצה. ואולם אם היא מצויה \u0003למטה מן המים\u0004 סמוך לקרקעית הבור, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003הא עריבי מיא\u0004 \u0005[הרי מתערבים המים]\u0006 מעליה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003לא שמיע לך הא\u0004 \u0005[שמעת\u0006 דבר \u0005זה]\u0006 ש\u0003אמר רב יהודה אמר רב, ומטו\u0004 \u0005[ו\u0006יש \u0005שהגיעו]\u0006 \u0003בה,\u0004 ביחוס שמועה זו \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' חייא: צריך שיראו ראשן של קנים\u0004 המשמשים כמחיצה \u0003למעלה מן המים טפח,\u0004 ואם כן יש מחיצה גמורה בין מלמעלה בין מלמטה.","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה: \"למעלה — למעלה מן המים\". מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003למעלה ממש\u0004 ש\u0003לא\u0004 — \u0003דעריבי מיא\u0004 \u0005[שמתערבים המים],\u0006 הלוא \u0003למעלה מן המים נמי\u0004 \u0005[גם כן]\u0006 \u0003הא עריבי מיא\u0004 \u0005[מתערבים המים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003לא שמיע לך הא דתני\u0004 \u0005[שמעת\u0006 דבר \u0005זה ששנה]\u0006 \u0003יעקב קרחינאה\u0004 (מקרחינא): \u0003צריך שישקע ראשי קנים\u0004 המשמשים מחיצה בתוך ה\u0003מים טפח,\u0004 ונמצא שהמחיצה מחלקת גם את מי הבור.","ושאל: \u0003ואלא הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 ש\u0003אמר רב יהודה: קורה ארבע מתרת בחורבה,\u0004 שקורה שרוחבה ארבעה טפחים המצויה מעל למחיצות חורבה הרי קצה הקורה מכל צד נחשב כיורד עד למטה וסותם את המעבר, וכאילו היה סתום במחיצה, ומותר לטלטל תחתיה, \u0003ורב נחמן אמר רבה בר אבוה:\u0004"],["\u0003קורה ארבעה מתרת במים\u0004 אם היתה מונחת על בור שבין שתי חצירות.","והלוא אפשר לשאול: \u0003הא קא אזיל\u0004 \u0005[הלוא הולך]\u0006 ה\u0003דלי\u0004 ששואב בו \u0003לאידך גיסא\u0004 \u0005[לצד השני]\u0006 מתחת לקורה, \u0003ומייתי\u0004 [\u0005ומביא]\u0006 מים מן החצר האחרת? ומשיבים: \u0003קים להו לרבנן\u0004 \u0005[מוחזק להם לחכמים]\u0006 ש\u0003אין דלי מהלך יותר מארבעה טפחים\u0004 הצידה מן המקום ממנו הורידוהו, ולכן הדלי נשאר בצד המחיצה שקבעו לו מתחילה.","ומקשים: \u0003תחת קורה מיהא הא עריבי מיא\u0004 \u0005[בכל אופן הרי מתערבים המים],\u0006 ונמצא שהדלי מעלה מים של החצר השניה! \u0003אלא\u0004 יש לומר כי אין הטעם משום חציצה ממשית אלא \u0003משום דקל\u0004 \u0005[שקולא,\u0006 הקלה\u0005]\u0006 \u0003הוא שהקילו חכמים במים,\u0004 שמחיצה התלויה מעל המים נחשבת כסותמת. \u0003כדבעא מיניה\u0004 \u0005[כמו ששאל ממנו]\u0006 \u0003ר' טבלא מרב: מחיצה תלויה, מהו שתתיר בחורבה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין מחיצה תלויה מתרת אלא במים, קל הוא שהקילו חכמים במים.\u0004","שנינו במשנה: \u0003אמר ר' יהודה\u0004 שאין צורך במחיצה בבור, ש\u0003לא תהא מחיצה\u0004 של תוך הבור חשובה מן הכותל שעל הבור. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: ר' יהודה בשיטת ר' יוסי אמרה,\u0004 ש\u0003אמר\u0004 ר' יוסי: \u0003מחיצה תלויה מתרת אפילו ביבשה,\u0004 ונחשבת כיורדת עד למטה וסותמת.","ולכן לדעתו אין המחיצה צריכה להיות קבועה כלל בתוך חלל הבור, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המשלשל\u0004 \u0005[אורג]\u0006 \u0003דפנות\u0004 של סוכה \u0003מלמעלה למטה, בזמן שגבוהות\u0004 הדפנות \u0003מן הארץ שלשה טפחים — פסולה,\u0004 שאין הן נחשבות כמחיצות לסוכה, ואולם אם עשה מחיצות \u0003ממטה למעלה, אם גבוהות עשרה טפחים,\u0004 אף על פי שאינן מגיעות לסכך — \u0003כשירה.\u0004","ואילו \u0003ר' יוסי אומר: כשם שמלמטה למעלה\u0004 די ב\u0003עשרה\u0004 טפחים, \u0003כך מלמעלה למטה עשרה,\u0004 אפילו גבוהים הרבה מעל הארץ, נידונים כדופן שלימה. וכן סבר ר' יהודה שמחיצה התלויה מעל הבור נחשבת כיורדת וסותמת.","ודוחים: \u0003ולא היא,\u0004 אין הדבר כן ואפשר לחלק בין השיטות ולומר כי \u0003לא ר' יהודה סבר לה כר' יוסי ולא ר' יוסי סבר לה כר' יהודה.\u0004","\u0003ומפרטים: ר' יהודה לא סבר לה כר' יוסי\u0004 כי יש לחלק \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה\u0004 עקרון זה \u0003אלא בעירובי חצירות\u0004 שהן \u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003אבל סוכה דאורייתא\u0004 \u0005[ש\u0006היא \u0005מן התורה]\u0006 — \u0003לא\u0004 אמר שאפשר לסמוך על מחיצות תלויות.","\u0003ו\u0004כן \u0003לא ר' יוסי סבר כר' יהודה,\u0004 כי \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי אלא בסוכה\u0004 ש\u0003איסור עשה הוא,\u0004 שהרי מצות סוכה היא מצות עשה שאין נענשים מן התורה בבית דין על ביטולה, ואין להחמיר בה עד כדי כך. \u0003אבל שבת\u0004 שהיא \u0003איסור סקילה, שהיא חמורה ביותר והעובר עליה נידון בסקילה — לא אמר\u0004 ר' יוסי, ושמא מודה הוא שבכל דיני שבת — אף אלה שהם דברי סופרים — יש להחמיר ביותר.","\u0003ואם תאמר אותו מעשה שנעשה בציפורי\u0004 שסמכו על מחיצות תלויות ביבשה בשבת, \u0003על פי מי נעשה?\u0004 אם כפי שאמרנו לא ר' יוסי הוא, והלוא ר' יוסי הוא שהיה הסמכות ההלכתית הקובעת בציפורי! יש לומר ש\u0003לא על פי ר' יוסי\u0004 נעשה, \u0003אלא\u0004 לאחר פטירתו, ו\u0003על פי ר' ישמעאל בר' יוסי נעשה,\u0004 והוא סבר שמחיצה תלויה מתירה אף בשבת ואף ביבשה.","וכך היה מעשה \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: פעם אחת שכחו ולא הביאו\u0004 מבית שבחצר אחרת \u0003ספר תורה מבעוד יום\u0004 לבית הכנסת, ולא היה ספר לקרוא בו. \u0003למחר פרסו סדין על העמודים\u0004 שהיו בין בית הכנסת והבית שהיה בו הספר, וסדינים אלה יצרו כעין מסדרון שמחיצותיו תלויות מכל צד, \u0003והביאו ספר תורה וקראו בו.\u0004","ותוהים על הלשון, וכי \u0003פרסו\u0004 בשבת סדינים?! \u0003לכתחלה מי שרי\u0004 \u0005[האם מותר]\u0006 לעשות כן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003הכל מודים שאין עושין אהל עראי\u0004 מלכתחילה \u0003בשבת\u0004 והפורס סדינים על העמודים הרי הוא כעושה אוהל.","\u0003אלא\u0004 יש לומר: \u0003מצאו סדינים פרוסין על העמודים\u0004 וסמכו עליהם משום מחיצה, \u0003ו\u0004על ידי כך \u0003הביאו ספר תורה וקראו בו.\u0004","\u0003אמר רבה: ר' יהודה ור' חנניא בן עקביא אמרו דבר אחד\u0004 שהקלו מאד בדין מחיצה שעל המים. \u0003ר' יהודה, הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 ואילו \u0003ר' חנניא בן עקביא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003ר' חנניא בן עקביא אומר: גזוזטרא שיש בה\u0004 שטח \u0003ארבע אמות על ארבע אמות\u0004 והיא תלויה מעל למים"],["\u0003חוקק בה\u0004 חור של \u0003ארבע\u0004 טפחים \u0003על ארבע\u0004 טפחים \u0003וממלא\u0004 דרכה מים. משום שמדמים כאילו רצפת הגזוזטרא שמסביב לחור מתכופפת ויוצרת מחיצות גבוהות עשרה טפחים מכל צד וצד של החור שבאמצע, ומכח מחיצות תלויות אלה מותר למלא מים דרך שם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ודילמא\u0004 \u0005[ושמא]\u0006 \u0003לא היא,\u0004 אינו כן, ויש לחלק בין השיטות, ובאופן זה, \u0003עד כאן לא שמענו שאמר ר' יהודה התם\u0004 \u0005[שם]\u0006 \u0003אלא שאמר\u0004 שיש לסמוך על הכלל ההלכתי \u0003\"גוד אחית מחיצתא\"\u0004 \u0005[משוך\u0006 ו\u0005הורד את המחיצה],\u0006 שמחיצה המצויה מעל הבור נחשיבנה כאילו היא יורדת עד תחתיתה. \u0003אבל \"כוף וגוד\"\u0004 \u0005[כפוף\u0006 מחיצה \u0005ומשוך]\u0006 אותה עד למטה, כפי שהציע ר' חנניא בן עקביא — אינו מקבל.","\u0003ו\u0004כן גם אפשר לומר ש\u0003עד כאן לא\u0004 שמענו ש\u0003אמר ר' חנניא בן עקביא התם\u0004 \u0005[שם]\u0006 בגזוזטראות \u0003אלא בימה של טבריא, הואיל ויש לה אוגנים\u0004 \u0005[גדות]\u0006 ניכרות מסביב, \u0003ועיירות וקרפיפות מקיפות אותה\u0004 מכל צד, הרי ים כנרת כולו תחום מסביב, ונראה קצת כרשות היחיד, ולכן די בתקנה קלה כעין זו, \u0003אבל בשאר מימות\u0004 — \u0003לא\u0004 התיר ר' חנניא בן עקביא.","\u0003אמר אביי: ולדברי ר' חנניא בן עקביא,\u0004 אם \u0003היתה\u0004 רצפת הגזוזטרא \u0003סמוכה לכותל\u0004 של הבית שאליו היא מחוברת בזיזים \u0003בפחות משלשה טפחים — צריך שיהא אורכה ארבע אמות, ו\u0004די שיהא \u0003רוחבה אחד עשר ומשהו\u0004 טפחים. כיון שהכותל עצמו הוא מחיצה אחת, ואורך הגזוזטרא של ארבע אמות נחשב כסותם משני צידי הבור, ואם כן די שיהא רוחבה רק אחד עשר טפחים ומשהו, שטפח ומשהו משלים לרוחב הנקב, ועשרה טפחים הנותרים נחשבים ככפופים וסותמים את החור מצידו הרביעי.","ואם \u0003היתה\u0004 הגזוזטרא \u0003זקופה\u0004 שהיו לה מחיצות זקופות מסביב (ר\"ח) — \u0003צריך שיהא גובהה\u0004 של המחיצה \u0003עשרה טפחים, ורוחבה\u0004 של המרפסת \u0003ששה טפחים ושני משהויין,\u0004 כדי שיהא מכל צד של החור, שהוא בן ארבעה טפחים, טפח ומשהו לעמוד עליו.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: היתה עומדת בקרן זוית\u0004 בין שני כתלים (ר\"ח) \u0003צריך שיהא גובהה של המחיצה עשרה טפחים ורוחבה של המרפסת שני טפחים ושני משהויין,\u0004 שהרי יכול הוא לעמוד על מחיצות אלו ואז יש לו מחיצות של ממש.","ושואלים: \u0003ואלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' חנניא בן עקביא אומר: גזוזטרא שיש בה ארבע אמות על ארבע אמות — חוקק בה ארבעה על ארבעה\u0004 טפחים \u0003וממלא, היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 שהרי הסברנו שבכל אופן שהגזוזטרא סמוכה לקיר אין צורך בגודל זה?","ומשיבים: \u0003דעבידא כי אסיתא\u0004 \u0005[שעשויה כעין מדוכה],\u0006 שהגזוזטרא עומדת במים על עמודים משל עצמה ורחוקה הרבה מכל כותל, ואת המחיצות שמחשיבים בה יש להוציא מתוך רוחבה שלה, ולכן צריכה שתהיה ארבע אמות על ארבע אמות.","\u0003אמת (תעלה) המים שהיא עוברת בחצר — אין ממלאין הימנה בשבת, אלא אם כן עשו לה בשפתה מחיצה גבוה עשרה טפחים בכניסה\u0004 שלה לחצר \u0003וביציאה\u0004 שלה מהחצר. \u0003ר' יהודה אומר:\u0004 אינו צריך למחיצה מיוחדת, שהרי \u0003כותל שעל גבה\u0004 שהוא כותל החצר \u0003תידון משום מחיצה.\u0004","\u0003אמר ר' יהודה:\u0004 הלוא \u0003מעשה באמה\u0004 (תעלת המים) שהיתה עוברת בתוך חצרותיה \u0003של\u0004 העיר \u0003אבל, שהיו ממלאין ממנה על פי זקנים בשבת,\u0004 משום שהסתמכו על כותל החצר שהיה תלוי מעליה! \u0003אמרו לו:\u0004 טעמו של דבר היה \u0003מפני שלא היה בה כשיעור\u0004 רוחב ועומק האוסרים, ולכן מותר היה אף בלא מחיצה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשו לה\u0004 לתעלת מים זו מחיצה \u0003בכניסה, ולא עשו לה ביציאה.\u0004 או ש\u0003עשו לה ביציאה, ולא עשו לה בכניסה — אין ממלאין הימנה בשבת, אלא אם כן עשו לה מחיצה\u0004 גבוהה \u0003עשרה טפחים ביציאה ובכניסה. ר' יהודה אומר: כותל החצר שעל גבה תידון משום מחיצה, ואין צורך במחיצה מיוחדת.\u0004","\u0003אמר ר' יהודה מעשה באמת המים שהיתה באה מאבל לצפורי, והיו ממלאין הימנה בשבת על פי הזקנים\u0004 בלא מחיצה נוספת.","\u0003אמרו לו:\u0004 וכי \u0003משם\u0004 אתה מביא \u0003ראיה?!\u0004 טעמו של דבר \u0003מפני שלא היתה עמוקה עשרה טפחים או שלא היה רוחבה ארבעה,\u0004 וכיון שכן אינה חשובה, שאין לה שיעור רשות לעצמה, ולכל הדעות מותר לשאוב ממנה בלא מחיצה נוספת.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אמת המים העוברת בין החלונות\u0004 שבין שני בתים, דינה ככרמלית, ואם היתה \u0003פחות משלשה\u0004 טפחים — \u0003משלשל דלי\u0004 מן החלון \u0003וממלא.\u0004 אם היתה \u0003שלשה — אין משלשל דלי וממלא.\u0004 ואילו \u0003רבן שמעון בן גמליאל אומר: פחות מארבעה — משלשל דלי וממלא,\u0004 ב\u0003ארבעה\u0004 טפחים — \u0003אין משלשל דלי וממלא.\u0004","ושואלים: מידה זו של שלושה וארבעה טפחים, \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר\u0006 שמדובר\u0005]\u0006 \u0003באמת המים גופה\u0004 אם היה רוחבה שלושה או ארבעה טפחים, \u0003ואלא הא\u0004 \u0005[זו]\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי מארץ ישראל אמר בשם ר' יוחנן: אין כרמלית פחותה מארבעה\u0004 טפחים —","\u0003לימא כתנאי\u0004 \u0005[האם תאמר\u0006 שבמחלוקת \u0005תנאים]\u0006 \u0003אמרה לשמעתיה\u0004 \u0005[את שמועתו],\u0006 ואינה מקובלת על הכל?","\u0003אלא\u0004 יש לומר שמדובר כאן \u0003ב\u0004רוחבם של \u0003אגפיה\u0004 של גדות התעלה. והשאלה היתה לגבי החלפה, האם מותר \u0003להחליף\u0004 את הדלי מן החלון (שהוא רשות היחיד) דרך האגפיים שהוא מקום פטור, אל התעלה (שהיא ככרמלית).","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מקום שאין בו ארבעה על ארבעה — מותר\u0004 גם \u0003לבני רשות היחיד ו\u0004גם \u0003לבני רשות הרבים לכתף עליו, ובלבד שלא יחליפו,\u0004 והרי כאן התיר להחליף דרך מקום פטור.","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003רשויות דאורייתא\u0004 \u0005[שמן התורה]\u0006 גזרו חכמים שלא יחליף דרך מקום פטור שמא יבוא להעביר במישרין."],["\u0003הכא\u0004 \u0005[כאן]\u0006 מדובר ב\u0003רשויות דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 וכיון שקלות הן, לא גזרו בהן שלא יחליפו דרך מקום פטור.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוחנן ברשויות דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אמר\u0004 שאסור להחליף בין שתי רשויות דרך מקום פטור, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כותל שבין שתי חצירות, גבוה עשרה טפחים ורוחב ארבעה — מערבין שנים\u0004 שני עירובים, בכל חצר לעצמה, \u0003ואין מערבין אחד\u0004 לשתיהן יחד.","\u0003היו בראשו\u0004 של כותל זה \u0003פירות — אלו\u0004 בני חצר אחת \u0003עולין מכאן ואוכלין, ואלו\u0004 בני החצר האחרת \u0003עולין מכאן ואוכלין.\u0004","ואם \u0003נפרץ הכותל,\u0004 אם היתה הפירצה \u0003עד עשר אמות — מערבין שנים, ואם רצו מערבין אחד, מפני שהוא\u0004 שפירצה שרחבה פחות מעשר אמות עדיין דינה \u0003כפתח.\u0004 ופירצה \u0003יותר מכאן\u0004 — הרי זו מבטלת את המחיצה, ו\u0003מערבין\u0004 עירוב \u0003אחד ואין מערבין שנים\u0004 שדינם כחצר אחת.","\u0003והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה\u0004 בבעיה זו: \u0003אין בו\u0004 באותו כותל רוחב \u0003ארבעה\u0004 טפחים \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003אמר רב: אויר שתי רשויות שולטת בו,\u0004 שכיון שאין בה שיעור מקום חשוב לעצמו, יש לשתי החצירות שייכות בראש הכותל \u0003ולא יזיז בו מלא נימה,\u0004 שכן האחת אוסרת על חבירתה.","\u0003ור' יוחנן אמר: אלו\u0004 בני חצר זו \u0003מעלין מכאן ואוכלין, ואלו מעלין מכאן ואוכלין,\u0004 אבל אינם מחליפים.","\u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לשיטתו],\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מקום שאין בו ארבעה על ארבעה\u0004 טפחים — \u0003מותר לבני רשות הרבים ולבני רשות היחיד לכתף עליו, ובלבד שלא יחליפו!\u0004 שגזר ר' יוחנן בהחלפה בין שתי רשויות, אפילו ברשויות שמדברי סופרים.","ומתרצים: ההלכה \u0003ההיא\u0004 שאסור להחליף \u0003זעירי אמרה\u0004 בשם ר' יוחנן, ואילו רב דימי חולק עליו בדעת ר' יוחנן. ומקשים: ומכל מקום \u0003לזעירי קשיא הא\u0004 \u0005[קשה\u0006 הלכה \u0005זו]\u0006 שבאמת המים התירו להחליף בין שתי גדותיה!","ומשיבים כי \u0003זעירי מוקים לה\u0004 \u0005[מעמיד אותה]\u0006 \u0003באמת המים גופה,\u0004 שמחלוקת רבן שמעון בן גמליאל וחכמים היתה לענין רוחבה של אמת המים עצמה ונחלקו בבעיה העקרונית מה רחבה של כרמלית. \u0003ו\u0004לדעתו, שיטת \u0003רב דימי\u0004 שאין כרמלית אלא ברוחב ארבעה טפחים \u0003תנאי\u0004 \u0005[\u0006במחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 שנויה.","ומקשים \u0003ותהוי\u0004 \u0005[ותהא]\u0006 אמת המים אף שאין בה שיעור מקום חשוב \u0003כי\u0004 \u0005[כמו]\u0006 \u0003חורי כרמלית\u0004 ותיחשב כחלק ממנה, שהרי חורים הסמוכים לרשות היחיד אף אם אין בהם שיעור חשוב דינם כרשות היחיד, וכן הדין בחורים הסמוכים לרשות הרבים שהם כמותה, ואף כאן תהא אמת המים בחצר בטלה לאמת המים שברחוב ותדון ככרמלית עצמה!","ומשיבים: \u0003אביי בר אבין ורב חנינא בר אבין דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין\u0004 דין \u0003חורין לכרמלית\u0004 כי מאחר שכרמלית היא רשות שמדברי סופרים בלבד, אין אנו מחמירים בה לספח אליה גם את החורים הסמוכים לה.","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 בכלל ש\u0003יש חורין לכרמלית — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דוקא \u0003בסמוכה,\u0004 שאם היתה הכרמלית סמוכה לחורים הריהם בטלים. ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 באמת המים, הרי \u0003מופלגת\u0004 (רחוקה) היא ואין לה דין כרמלית.","\u0003רבינא אמר\u0004 שלמחלוקת רבן שמעון בן גמליאל אפשר לתת הסבר אחר: שלא נחלקו לא ברוחב אמת המים ולא ברוחב אגפיה אלא מדובר \u0003כגון דעבד\u0004 \u0005[שעשה]\u0006 \u0003לה\u0004 לאמת המים \u0003ניפקי אפומה\u0004 \u0005[מוצאות בפתחה],\u0006 כעין גידודים מכאן ומכאן, שהיה בין הגידודים רווח מסויים.","\u0003ואזדו רבנן לטעמייהו\u0004 \u0005[והלכו חכמים לשיטתם]\u0006 שבפחות משלושה הרי הוא לבוד, ואם היה הפתח פחות משל שלושה טפחים הרי הוא כסגור לחלוטין, אבל בארבעה לא. \u0003ורבן שמעון בן גמליאל לטעמיה\u0004 \u0005[לשיטתו\u0006 שלו\u0005]\u0006 שדין לבוד הוא ארבעה טפחים.","\u0003גזוזטרא שהיא למעלה מן המים — אין ממלאין הימנה\u0004 מהמים דרך הגזוזטרא \u0003בשבת, אלא אם כן עשו לה\u0004 לגזוזטרא מסביב \u0003מחיצה גבוהה עשרה טפחים.\u0004 וממלאים דרך אותה מחיצה, \u0003בין\u0004 שעשו את המחיצה \u0003מלמעלה\u0004 מעל לגזוזטרא, ומחשיבים את מחיצותיה כיורדות עד למטה, \u0003בין\u0004 שעשו \u0003מלמטה\u0004 תחת הגזוזטרא.","\u0003וכן\u0004 אם היו \u0003שתי גזוזטראות זו למעלה מזו\u0004 שהיו סמוכות זו לזו, ו\u0003עשו\u0004 מחיצה \u0003לעליונה ו\u0004אולם \u0003לא עשו לתחתונה — שתיהן אסורות\u0004 למלאות מים מן העליונה \u0003עד שיערבו\u0004 זו עם זו.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003חנניא בן עקביא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003חנניא בן עקביא אומר: גזוזטרא שיש בה ארבע על ארבע אמות — חוקק בה\u0004 חור של \u0003ארבעה על ארבעה\u0004 טפחים, \u0003וממלא.\u0004 שאנו מחשיבים את קרקעית הגזוזטרא כאילו היתה מתכופפת ויוצרת מחיצה גבוהה עשרה מסביב לנקב, ואין צורך במחיצה נוספת.","\u0003אמר ר' יוחנן משום ר' יוסי בן זימרא: לא התיר ר' חנניא בן עקביא\u0004 היתר זה בגזוזטרא שאינה מוקפת מחיצה \u0003אלא בימה של טבריא\u0004 (בים כנרת), \u0003הואיל ויש לה\u0004 לימת הכנרת \u0003אוגנים\u0004 (גדות ניכרות הנראות לעין מכל צד), \u0003ועיירות וקרפיפות מקיפות אותה\u0004 והרי היא נראית כחלק מהישוב, \u0003אבל בשאר מימות\u0004 כגון בימים גדולים — \u0003לא\u0004 התיר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה דברים התיר ר' חנניא בן עקביא לאנשי טבריא,\u0004 ואלו הם: \u0003ממלאין מים\u0004 מן הים \u0003מגזוזטרא\u0004 בת ארבע אמות על ארבע אמות \u0003בשבת, וטומנין\u0004 פירות \u0003בעצה\u0004 \u0005[בפסולת\u0006 הקטניות\u0005],\u0006 \u0003ומסתפגין בשבת באלונטית\u0004 \u0005[במגבת]\u0006 ומבארים:","\u0003ממלאין מים מגזוזטרא בשבת — הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 \u0003וטומנין בעצה מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 הלכה זו, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השכים להביא פסולת\u0004 קש ותבואה מהשדה כדי לטמון בהם את הפירות, \u0003אם\u0004 השכים \u0003בשביל שיש עליו\u0004 על הפסולת עדיין \u0003טל\u0004 ורצה שיתלחלחו פירותיו בטל — \u0003הרי הוא ב\"כי יתן\",\u0004 שאפשר אז לקרוא בו המקרא \"וכי יתן מים על זרע ונפל מנבלתם עליו טמא היא לכם\" (ויקרא יא, לח) שהוכשרו הפירות שנטמנו בו לקבל טומאה על ידי מים אלה,","\u0003ואם\u0004 השכים רק \u0003בשביל שלא יבטל ממלאכתו\u0004 ורוצה בפירות — \u0003אינו ב\"כי יתן\"\u0004 שאינו מתכוון שיהא הטל על הפירות, ומים שניתנו שלא בכוונה אינם מכשירים לטומאה. \u0003וסתם\u0004 הקביעות בהשכמת"],["\u0003אנשי טבריא\u0004 כדי להביא פסולת קש מן השדה להטמנת פירותיהם הוא \u0003כמי שלא יבטל ממלאכתו דמי\u0004 \u0005[נחשב],\u0006 שרובם היו בעלי מלאכה ועסוקים במלאכתם, ומן הסתם עושים זאת רק שלא לאחר למלאכתם.","\u0003ומסתפגין באלונטית\u0004 \u0005(במגבת),\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 הלכה זו, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בשבת וביום טוב \u0003מסתפג אדם\u0004 שרחץ עצמו בצונן \u0003באלונטית,\u0004 ואין חוששים שמא יסחטנה. \u0003ומניחה בחלון\u0004 של בית המרחץ ולא יתננה לאחר, שמא ישכח ויסחוט. \u0003ולא ימסרנה לאוליירין\u0004 \u0005[בלנים]\u0006 \u0003מפני שחשודין על אותו דבר,\u0004 שמא יסחטו את המגבות ויתנו אותן למתרחצים האחרים. \u0003ר' שמעון אומר: אף מביאה\u0004 לאלונטית \u0003בידו לתוך ביתו,\u0004 ואין לחשוש שמא יסחוט. ובכגון זה התיר ר' חנניא בן עקביא.","\u0003אמר רבה בר רב הונא: לא שנו\u0004 היתר זה בתיקון הגזוזטרא \u0003אלא\u0004 לענין \u0003למלאות\u0004 מים ולהעלותם דרך הנקב לגזוזטרא, \u0003אבל לשפוך\u0004 שופכין ממנה ולמטה דרך נקב זה — \u0003אסור.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שיזבי: וכי מה בין זה לעוקה\u0004 (לבור) שאמרו חכמים במשנה (להלן) שאם עושה בור שמחזיק בתוכו סאתים בחצר שגודלה פחות מארבע אמות, יכול לשפוך בו שופכין, ואינו צריך לחשוש אם התמלא מבעוד יום, ובשבת המים יוצאים מן החצר.","ומשיבים: \u0003הני\u0004 \u0005[אלה]\u0006 המים הנשפכים לחצר \u0003תיימי\u0004 \u0005[נגמרים]\u0006 ועשויים להיבלע מעט מעט באדמה, ואין ודאות שהמים אמנם יצאו מחוץ לחצירו, ולכן מותר לשפוך לתוכם. \u0003והני\u0004 \u0005[ואלה]\u0006 המים הנשפכים לאגם \u0003לא תיימי\u0004 \u0005[נגמרים]\u0006 ונמצא שיודע בודאי ששופך מים חוץ לתחום המותר לו, ולכך אסור.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר רבה בר רב הונא, לא תימא\u0004 \u0005[תאמר]\u0006 \u0003למלאות הוא דשרי\u0004 \u0005[שמותר],\u0006 \u0003לשפוך אסור, אלא לשפוך נמי שרי\u0004 \u0005[גם כן מותר].\u0006 \u0003אמר רב שיזבי: פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא שהרי \u0003היינו\u0004 \u0005[הריהו]\u0006 בדיוק כענין \u0003עוקה\u0004 ששנינו במשנתנו! ואם תנסה לדחות: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 יש הבדל בין הדברים, כי \u0003הני תיימי\u0004 \u0005[אלה,\u0006 מי העוקה יכולים \u0005לכלות]\u0006 \u0003והני\u0004 \u0005[ואלה\u0006 הנשפכים למים\u0005]\u0006 \u0003לא תיימי\u0004 \u0005[כלים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין לחלק.","שנינו במשנה: \u0003וכן שתי גזוזטראות זו\u0004 מעל זו אין שואבים מאחת מהן אף שעשו לה מחיצה, אלא אם כן עירבו הגזוזטראות ביניהן. \u0003אמר רב הונא אמר רב: לא שנו\u0004 שיש איסור בכך \u0003אלא בסמוכה\u0004 שהיתה גזוזטרא אחת סמוכה לחברתה. \u0003אבל במופלגת\u0004 אם היתה רחוקה ממנה ארבעה טפחים — \u0003עליונה מותרת\u0004 אם היתה בה מחיצה לעצמה.","\u0003ורב לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר רב: אין אדם אוסר על חבירו דרך אויר,\u0004 שכיון שהגזוזטרא התחתונה רחוקה, אינה אוסרת על חברתה, אף שבדוחק יכולה היא להשתמש בה דרך האויר (החלל) הפנוי שביניהן.","\u0003אמר רבה אמר ר' חייא, ורב יוסף אמר ר' אושעיא: יש גזל בשבת,\u0004 כלומר יכול להשתמש ברשותם של אחרים בשבת, והרי רשות זו נקנית לו. \u0003וחורבה מחזיר לבעלים\u0004 כלומר, המקום כגון חורבה שהשתמש בה, אינו יכול להחזיק בה לעצמו וצריך להחזירה לבעלים, ולכך אסור לו להשתמש בה בשבת.","ותוהים: \u0003הא גופא קשיא\u0004 \u0005[\u0006הלכה \u0005זו עצמה קשה],\u0006 \u0003אמרת \"יש גזל בשבת\" אלמא\u0004 \u0005[מכאן]\u0006 משמע ש\u0003קניא\u0004 \u0005[נקנה]\u0006 המקום ללוקחו להשתמש בו, אף שאינו שלו. וחזר ואמר: \u0003\"חורבה מחזיר לבעלים\". אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לא קניא!\u0004","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 נתכוון\u0005],\u0006 לא כפי שהבנו תחילה אלא \u0003יש דין גזל בשבת\u0004 כלומר אף שימוש בשבת קרוי גזל וצריך להשיבו לבעליו. \u0003כיצד — שחורבה מחזיר לבעלים\u0004 ואינו זוכה בה אף לצורך שימוש של שבת בלבד.","\u0003אמר רבה: ומותבינן אשמעתין\u0004 \u0005[ומקשים אנו\u0006 בעצמנו על \u0005ההלכה שלנו]\u0006 שהרי שנינו: \u0003וכן שתי גזוזטראות זו למעלה מזו\u0004 הרי זו אוסרת על זו. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003יש דין גזל בשבת,\u0004 ואין אדם רשאי להשתמש ברשותו של אחר, ואם השתמש לא קנה כל זכות, אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אסורות\u0004 שתי הגזוזטראות? הלוא אין לתחתונה רשות להשתמש בעליונה!","\u0003אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שעשו מחיצה\u0004 לעליונה \u0003בשותפות,\u0004 ויש זכות שותפות לבני התחתונה בגזוזטרא העליונה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003עשו לתחתונה\u0004 מחיצה לעצמם, \u0003נמי\u0004 \u0005[גם כן]\u0006 עדיין יהיו בני העליונה אסורים, שהרי התחתונים עדיין שותפים הם גם בעליונה ואוסרים!","ומשיבים: \u0003כיון\u0004 ש\u0003עשו לתחתונה — גלוי גלי\u0004 \u0005[גילתה\u0006 הגזוזטרא התחתונה\u0005]\u0006 את \u0003דעתה דאנא בהדך\u0004 \u0005[שאני אתך]\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי,\u0004 כלומר שעל ידי עשיית מחיצה לעצמם סילקו עצמם משותפות זו ושוב אינם אוסרים.","\u0003חצר שהיא פחותה\u0004 בשטחה \u0003מארבע אמות — אין שופכין בתוכה מים בשבת, אלא אם כן עשו לה\u0004 בתוכה \u0003עוקה\u0004 (בור) ש\u0003מחזקת סאתים מן הנקב ולמטה,\u0004 כלומר שהיה חללה בנפח זה.","\u0003בין\u0004 שעשו אותה \u0003מבחוץ\u0004 לחצר, \u0003בין מבפנים\u0004 בחצר עצמה. \u0003אלא ש\u0004אם היתה העוקה \u0003מבחוץ — צריך לקמור,\u0004 לעשות כיסוי מעוגל מעל לגומה כדי שהמים יצאו למקום שאינו רשות הרבים. ואם היתה \u0003מבפנים — אין צריך לקמור.\u0004","\u0003ר' אליעזר בן יעקב אומר: ביב שהוא קמור ארבע אמות ברשות הרבים — שופכים לתוכו מים בשבת. וחכמים אומרים: אפילו גג או חצר\u0004 שאורכם \u0003מאה אמה — לא ישפוך על פי הביב\u0004 במישרין, \u0003אבל שופך הוא לגג והמים יורדין לביב\u0004 מעצמם.","ולגבי שטח ארבע אמות בחצר הרי \u0003החצר והאכסדרה\u0004 המרפסת הפתוחה \u0003מצטרפין לארבע אמות, וכן שתי דיוטאות\u0004 (דירות) \u0003זו כנגד זו\u0004 באותה חצר \u0003מקצתן עשו עוקה\u0004 בחצר \u0003ומקצתן לא עשו עוקה, את שעשו עוקה — מותרין\u0004 לשפוך מים, \u0003את שלא עשו עוקה — אסורין.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 קבעו גודל החצר בארבע אמות? \u0003אמר רבה: מפני שאדם עשוי להסתפק\u0004 (להשתמש) ב\u0003סאתים מים בכל יום,\u0004 ושיעור זה בשטח של \u0003ארבע אמות — אדם רוצה לזלפן,\u0004 כלומר לשפוך מים על החצר שלא ירבה בה האבק, ולכן גם אם יוצאים המים מן החצר אין כוונתו לכך בהכרח,"],["\u0003פחות מארבע\u0004 אמות — \u0003שופכן,\u0004 לפי שאין המקום ראוי לזלף בו. ולכן \u0003אי דעביד\u0004 \u0005[אם שעושה]\u0006 \u0003עוקה — שרי\u0004 \u0005[מותר],\u0006 אם \u0003לא — אסור, שהרי ודאי כוונתו שיצאו מחוץ לה.\u0004","\u0003ור' זירא אמר\u0004 טעם אחר: בחצר \u0003ארבע אמות — תיימי\u0004 \u0005[כלים]\u0006 המים ונבלעים בשטח זה, \u0003פחות מארבע אמות — לא תיימי\u0004 \u0005[כלים]\u0006 ויוצאים מחוץ לה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה הבדל ביניהם\u0006 למעשה\u0005]\u0006 בין הסבר זה להסבר הקודם? \u0003אמר אביי: בחצר אריך וקטין איכא בינייהו\u0004 \u0005[ארוכה וצרה יש ביניהם\u0006 הבדל\u0005],\u0006 שכיון ששטחה אף הוא שש עשרה אמות מרובעות, המים נבלעים בתוכה, ולדעת ר' זירא אינה צריכה עוקה. אבל מאחר שחצר כזו אינה צריכה שיזלפו בה מים לדעת רבה צריכה עוקה.","\u0003תנן\u0004 \u0005[שנינו]:\u0006 \u0003חצר ואכסדרה מצטרפין לארבע אמות, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' זירא, ניחא\u0004 \u0005[נוח\u0006 \u0003הדבר\u0004\u0005],\u0006 כי לשיטתו יש בכמות השטח המצורף כדי להסתפג בה מים. \u0003אלא לרבה קשיא\u0004 \u0005[קשה],\u0006 כי בשל האכסדרה שוב אין צורת ריבוע לחצר ואין מזלפים בה.","\u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003ר' זירא אליבא\u0004 \u0005[על פי]\u0006 שיטת \u0003רבה\u0004 שמדובר כאן \u0003באכסדרה מהלכת על פני כל החצר כולה\u0004 ומשלימה את רוחב החצר. והחצר עם האכסדרה הן יחד ריבוע של ארבע על ארבע אמות, ויש טעם לזלף על פני כל החצר.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה להכריע במחלוקת, ששנינו בברייתא: \u0003חצר שאין בה ארבע אמות על ארבע אמות — אין שופכין לתוכה מים בשבת. בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרבה ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שהרי לדבריו אם היא ארוכה וצרה אין שופכים לתוכה, \u0003אלא לר' זירא שלדבריו אין חשיבות אלא למידת השטח, קשיא\u0004 \u0005[קשה]!\u0006","\u0003אמר לך ר' זירא: הא מני\u0004 \u0005[\u0006דבר \u0005זה\u0006 של \u0005מי הוא]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 בסוף משנתנו, שלדעתם אין במידת השטח כל חשיבות, \u0003ו\u0004אילו \u0003מתניתין\u0004 \u0005[\u0006סתם \u0005משנתנו]\u0006 \u0003ר' אליעזר בן יעקב היא,\u0004 ולדבריו מידת השטח היא הקובעת.","ושואלים \u0003ומאי דוחקיה\u0004 \u0005[ומה דוחקו]\u0006 של \u0003ר' זירא לאוקמה למתניתין\u0004 \u0005[להעמיד את משנתנו]\u0006 \u0003כר' אליעזר בן יעקב? אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתנו היתה קשה לו],\u0006 \u0003מאי איריא דתני\u0004 \u0005[מה שייך,\u0006 מדוע דוקא \u0005ששנה]\u0006 \u0003\"חצר שהיא פחותה\u0004 מארבע אמות \u0003\",\u0004 שמשמע שאם יש בה ארבע על ארבע, אף שלא בריבוע, די להתיר לשפוך בה, \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003\"חצר שאין בה ארבע אמות על ארבע אמות\"\u0004 בריבוע, אף שיש בה שיעור זה!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003שמע מינה\u0004 \u0005[תלמד מכאן]\u0006 שהוא מדגיש כאן רק את השטח הכללי של החצר, וכשיטת \u0003ר' אליעזר בר יעקב היא.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומקשים על מסקנתנו: \u0003והא מדסיפא\u0004 \u0005[והרי מתוך שבסופה]\u0006 של המשנה מובאים במפורש דברי \u0003ר' אליעזר בן יעקב\u0004 משמע כי \u0003רישא לאו\u0004 \u0005[ההתחלה לא]\u0006 כשיטת \u0003ר' אליעזר בן יעקב\u0004 היא!","ודוחים: לא היא, כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' אליעזר בן יעקב היא. ו\u0004לענין הקושי הסגנוני, \u0003חסורי מיחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 המשנה, \u0005וכך יש לשנותה]:\u0006 \u0003חצר שהיא פחותה מארבע אמות — אין שופכין לתוכה מים בשבת. הא\u0004 \u0005[הרי]\u0006 אם היתה \u0003ארבע אמות — שופכין, שר' אליעזר בן יעקב אומר: ביב הקמור ארבע אמות ברשות הרבים שופכין לתוכו מים בשבת.\u0004","שנינו במשנה כי \u0003ר' אליעזר בן יעקב אומר: ביב הקמור\u0004 שופכים לתוכו בשבת, וחכמים מתירים רק לשפוך לגג שממנו ישפכו המים לביב מעצמם.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003חנניא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חנניא אומר: אפילו גג מאה אמה — לא ישפוך, לפי שאין הגג עשוי לבלוע\u0004 כלל \u0003אלא לקלח,\u0004 והשופך מים עליו הריהו כשופך במישרין החוצה.","\u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003במה דברים אמורים\u0004 שצריך עוקה — \u0003בימות החמה, אבל בימות הגשמים — שופך ושונה ואינו נמנע. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר רבא: אדם רוצה שיבלעו מים במקומם,\u0004 כלומר, כיון שמרובים המים בין כה וכה לא איכפת לו שהמים נבלעים בחצר או יוצאים ממנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והרי שופכין\u0004 הנשפכים לביב \u0003אדם רוצה שיבלעו\u0004 בתוך הביב ולא יצאו החוצה, ובכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003\"לא ישפוך\"!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בחורף \u0003למאי ניחוש לה\u0004 \u0005[למה נחשוש],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 אדם חושש \u0003משום קלקול חצרו — הא מיקלקלא וקיימא\u0004 \u0005[הרי\u0006 היא \u0005מקולקלת ועומדת]\u0006 בשל מי הגשמים. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום גזירה שמא יאמרו: \"צינורו של פלוני מקלח מים\u0004 בשבת \u0003\",\u0004 ושמא יחשבו שמשקה גינתו או עושה איסור אחר, ויבואו אף הרואים לעשות כן אף בימות החמה, שהרי יחשבו שמן הסתם הוא עושה כן בהיתר — הרי \u0003סתם צינורות מקלחים הם\u0004 בימות הגשמים, ואין חושדים.","\u0003אמר רב נחמן: בימות הגשמים עוקה מחזיק סאתים — נותנין לו\u0004 רשות לשפוך אליה מים \u0003סאתים, מחזיק סאה — נותנין לו סאה. בימות החמה,\u0004 מחזיק \u0003סאתים — נותנין לו סאתים,\u0004 מחזיק \u0003סאה — אין נותנין לו\u0004 רשות לשפוך מים \u0003כל עיקר,\u0004 שלא תיקנו חכמים בגודל זה.","ומקשים: \u0003בימות החמה נמי\u0004 \u0005[גם כן],\u0006 \u0003מחזיק סאה ניתיב ליה\u0004 \u0005[ניתן לו]\u0006 \u0003סאה,\u0004 שהרי אם יתן בו כשיעורו לא יצאו המים! ומשיבים! \u0003גזרה דלמא אתי\u0004 \u0005[שמא יבוא]\u0006 \u0003ליתן ליה\u0004 \u0005[בו]\u0006 \u0003סאתים.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 \u0003בימות הגשמים נמי\u0004 \u0005[גם כן]\u0006 \u0003ליגזור\u0004 כן!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בימות הגשמים אם ישפוך לתוכה יותר מבית קיבולה, \u0003מאי ניחוש\u0004 \u0005[מה נחשוש]\u0006 \u0003לה, אי\u0004 \u0005[אם]\u0006 \u0003משום קלקול — הא מקלקלא וקיימא\u0004 \u0005[הרי מקולקלת ועומדת],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום גזירה שמא יאמרו: \"צינורו של פלוני מקלח מים\"\u0004 — הלוא \u0003סתם צינורות מקלחין הן\u0004 בימות הגשמים.","\u0003אמר אביי: הלכך,\u0004 לפי טעם זה יכול לשפוך בעוקה קטנה \u0003אפילו כור ואפלו כוריים,\u0004 שכיון שכל הצינורות מקלחים מים, אין לחשוש.","שנינו במשנה: \u0003וכן שתי דיוטאות זו כנגד זו\u0004 וחצר ביניהם, שיכולה רק זו שעשה עוקב בחצר לשפוך אליה מים, וזו שלא עשתה אינה יכולה. \u0003אמר רבא\u0004 שדין זה קיים \u0003אפילו עירבו\u0004 שתי הדיוטות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום נפישא דמיא\u0004 \u0005[ריבוי המים]\u0006 שיש בשתי דיוטות יותר מבאחת, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחת לי\u0004 בין שהיתה זו \u0003עוקה ואחת לי גיסטרא\u0004 (כלי חרס סדוק) שעושים אותן בית קיבול למים. או \u0003בריכה\u0004 או \u0003עריבה\u0004 (סירה), \u0003אף על פי שנתמלאו מים מערב שבת — שופכין לתוכן מים בשבת!\u0004 הרי שאין אנו חוששים למים היוצאים כל עוד העוקה היא כשיעור.","\u0003אלא\u0004 יש לדחות נוסח זה של דברי רבא, ולומר ש\u0003אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר\u0005, כך נאמר]:\u0006 \u0003אמר רבא\u0004"],["\u0003לא שנו אלא שלא עירבו, אבל עירבו — מותרין.\u0004","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003לא עירבו מאי טעמא\u0004 \u0005[מה הטעם]\u0006 ש\u0003לא? אמר רב אשי: גזירה דילמא אתי לאפוקי ממאני דבתים להתם\u0004 \u0005[שמא יבוא להוציא\u0006 מים \u0005מהכלים שבבתים לשם]\u0006 לשפוך לעוקה, וכיון שלא עירבו — אסור להם.","","\u0003כל גגות העיר רשות אחת\u0004 הם ומותר לטלטל מגג לגג, גם אם לא עירבו דיירי הבתים ביניהם. שלא גזרו חכמים איסור טלטול בין הגגות, כיון שאין הטלטול בהם מצוי. \u0003ובלבד שלא יהא גג\u0004 אחד \u0003גבוה עשרה או נמוך עשרה\u0004 מן הגגות האחרים, אלו \u0003דברי ר' מאיר. וחכמים אומרים: כל אחד ואחד\u0004 מן הגגות \u0003רשות בפני עצמו\u0004 הוא, ואין לטלטל מזה לזה אלא אם כן עירבו בעלי הבתים שתחתיהם ביניהם. \u0003ר' שמעון אומר: אחד גגות ואחד חצירות ואחד קרפיפות\u0004 — כולם \u0003רשות אחת הן לכלים ששבתו לתוכן.\u0004 שכל כלי שנשאר עם כניסת השבת באחד מאלו, מותר לטלטלו ממקום למקום בין אלה. \u0003ו\u0004אולם \u0003לא לכלים ששבתו בתוך הבית\u0004 שאם היה כלי בבית עם כניסת השבת וטלטלו אותו לחצר, שוב אין מטלטלים אותו מחצר לחצר אלא אם כן עירבו.","","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003אביי בר אבין ור' חנינא בר אבין, ויתיב\u0004 \u0005[וישב]\u0006 \u0003אביי גבייהו\u0004 \u0005[עמם],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[וישבו\u0006 השנים \u0005ואמרו]:\u0006 \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן\u0005]\u0006 כי \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 \u0003כשם שדיורין חלוקין למטה\u0004 ואין מטלטלים בלי עירוב, \u0003כך דיורין חלוקין למעלה,\u0004 וכשם שאין מטלטלים מבית לבית בלא עירוב כך אין לטלטל בין הגגות. \u0003אלא ר' מאיר מאי קסבר\u0004 \u0005[מה הוא סבור]\u0006 מה נימוקו בזה? \u0003אי קסבר\u0004 \u0005[אם הוא סבור]:\u0006 \u0003כשם שדיורין חלוקין למטה, כך דיורין חלוקין למעלה, אמאי\u0004 \u0005[מדוע]\u0006 מתיר הוא בטלטול ביניהם, משום ש\u0003רשות אחת הן?\u0004 הלוא כל אחד רשות לעצמו הוא! \u0003ואי קסבר\u0004 \u0005[ואם הוא סבור]\u0006 ש\u0003אין חלוקין,\u0004 ש\u0003כל\u0004 מקום \u0003למעלה מעשרה\u0004 טפחים מן הקרקע \u0003רשות אחת היא,\u0004 אם כן \u0003אפילו גג גבוה עשרה ונמוך עשרה\u0004 מחביריו, כיון שהוא גבוה מעשרה טפחים \u0003נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לטלטל בו!","","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי:\u0004 האם \u0003לא שמיע לכו הא\u0004 \u0005[שמעתם\u0006 דבר \u0005זה]\u0006 ש\u0003אמר רב יצחק בר אבדימי, אומר היה ר' מאיר: כל מקום שאתה מוצא שתי רשויות,\u0004 כלומר מקומות הנבדלים זה מזה בגובה או בגבולות כהבדל שבין שתי רשויות, אף ש\u0003הן רשות אחת\u0004 מבחינת הגדרתן ההלכתית, \u0003כגון עמוד\u0004 המצוי \u0003ברשות היחיד גבוה עשרה ורחב ארבעה\u0004 טפחים, הרי כיון שיש במדותיו כדי הגדרתו כרשות היחיד לעצמה — \u0003אסור לכתף עליו.\u0004 וטעם הדבר: \u0003גזירה משום תל ברשות הרבים,\u0004 שהרי תל גבוה עשרה ורחב ארבעה ברשות הרבים הרי הוא רשות היחיד, והמטלטל מרשות הרבים אליו חייב מן התורה, ולכן אסר ר' מאיר בכגון זה אף בתוך רשות היחיד. \u0003הכי נמי\u0004 \u0005[כך\u0006 כאן בגגות \u0005גם כן],\u0006 אסר לטלטל לגג הנבדל מחבריו בגובה עשרה טפחים, \u0003גזירה משום תל ברשות הרבים.\u0004","\u0003סבור מינה\u0004 \u0005[סברו ממנה,\u0006 מהלכה זו\u0005]\u0006 אביי וחנינא בר אבין ש\u0003אפילו מכתשת ואפילו גיגית\u0004 ההפוכות ומצויות ברשות היחיד ויש בהן כדי שיעור רשות היחיד לעצמן, אסור לכתף עליהן לשיטת ר' מאיר.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר מר\u0004 \u0005[אדוני]\u0006 הוא רבה רבו; \u0003לא אמר ר' מאיר\u0004 לאסור \u0003אלא\u0004 ב\u0003עמוד ו\u0004כן ב\u0003אמת הריחיים\u0004 (המקום המוגבה שמעמידים עליו את הריחיים), \u0003הואיל ואדם קובע להן מקום\u0004 ואינו מטלטלם תדיר, דומים הם לתל שברשות הרבים. אבל דבר הראוי לטלטול, לא גזר בו.","ומקשים: \u0003והרי כותל שבין שתי חצרות\u0004 ש\u0003קבוע\u0004 הוא, \u0003ואמר רב יהודה: כשתימצי\u0004 \u0005[לכשתמצא]\u0006 \u0003לומר,\u0004 לכשתמצה ותדקדק בשיטתו, הרי \u0003לדברי ר' מאיר:\u0004 כל \u0003גגין רשות לעצמן,\u0004 כל \u0003חצירות\u0004 של רבים \u0003רשות לעצמן,\u0004 וכן כל \u0003קרפיפות רשות לעצמן.\u0004 ומטלטלים בין חצר לחצר, אף שאין מטלטלים מחצר לגג.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן \u0003דשרי לטלטולי\u0004 \u0005[שמותר לטלטל]\u0006 מחצר לחצר \u0003דרך הכותל\u0004 המפריד ביניהן, אף שכותל זה גבוה מעשרה טפחים, וקשה לשיטת ר' מאיר שאסר לטלטל למקום הנבדל בגובה עשרה טפחים!","בתירוץ קושי זה \u0003אמר רב הונא בר יהודה אמר רב ששת: לא\u0004 כפי שהבנו עד כה, אלא הכוונה היא שמותר \u0003להכניס ולהוציא\u0004 מחצר לחצר או מקרפף לקרפף \u0003דרך פתחים\u0004 שביניהם, אבל לא מעל הכותל שהוא כרשות מיוחדת לעצמה. נאמר במשנה ש\u0003חכמים אומרים\u0004 ש\u0003כל אחד ואחד\u0004 מן הגגות \u0003רשות בפני עצמו. איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בענין זה. \u0003רב אמר\u0004 לשיטת חכמים: \u0003אין מטלטלין בו\u0004 בכל גג \u0003אלא\u0004 בתוך \u0003ארבע אמות,\u0004 שכיון שחכמים דנים את הגגות כדין חצירות ממש, כיון שאסורים בטלטול מזה לזה והם פרוצים זה לזה, לפיכך אוסרים בטלטול גמור גם בתוכם. \u0003ושמואל אמר: מותר לטלטל\u0004 בכל גג בפני עצמו \u0003בכולו.\u0004","","ומעירים: \u0003במחיצות הניכרות\u0004 שהיו בכל גג מחיצות או אופן היכר אחר להבחין בין גג לגג השכן — \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חלוקים]\u0006 שמותר לטלטל בכל שטח הגג. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — \u0003הרי הוא במחיצות שאינן ניכרות\u0004 בין גג לגג, שאף שהבתים חלוקים בין בעלים שונים אבל למעלה נראים כגג אחד.","\u0003רב אמר: אין מטלטלין בו אלא בארבע אמות\u0004 בלבד כי \u0003לא אמר,\u0004 לא קיבל את העיקרון של \u0003\"גוד אסיק מחיצתא\"\u0004 \u0005[משוך\u0006 ו\u0005העלה את המחיצות]\u0006 שבין הבתים מלמטה, שנדון בהם כאילו נמשכו והגיעו עד למעלה מהגג ויעשו כמחיצות בין הגגות. \u0003ושמואל אמר: מותר לטלטל בכולו,\u0004 כי \u0003אמר\u0004 \u0005[סבר]:\u0006 \u0003\"גוד אסיק מחיצתא\"\u0004 \u0005[משוך\u0006 ו\u0005העלה את המחיצות].\u0006","\u0003תנן\u0004 \u0005[שנינו ב\u0006משנה\u0005],\u0006 \u0003וחכמים אומרים: כל אחד ואחד\u0004"],["\u0003רשות לעצמו\u0004 משמע מכאן לכאורה שכל גג הוא רשות מיוחדת לעצמו ומותר לטלטל בכולו. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003שמואל ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 \u0003אלא ל\u0004שיטת \u0003רב קשיא\u0004 \u0005[קשה].\u0006","ומשיבים: \u0003אמרי בי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 הכוונה שם אינה להתיר טלטול בכל הגג כולו, אלא להחמיר \u0003שלא יטלטל שתי אמות בגג זה, ושתי אמות בגג זה,\u0004 שאף ההיתר לטלטל ארבע אמות הוא בגג אחד בלבד.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: כי הוינן\u0004 \u0005[כאשר היינו]\u0006 \u0003בבבל הוה אמרינן\u0004 \u0005[היינו אומרים]:\u0006 \u0003בי\u0004 \u0005[\u0006בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמרו: אין מטלטלין בו\u0004 בגג זה \u0003אלא בארבע אמות, והני דבי\u0004 \u0005[ואותם\u0006 תלמידים \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל תנו\u0004 \u0005[שנו]\u0006 ברייתא לפי מסורת שבידם: \u0003אין להן אלא גגן.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"אין להן אלא גגן\" — לאו דשרו לטלטולי בכוליה\u0004 \u0005[האם לא שמותר לטלטל בכולו]?\u0006 וקשה מברייתא זו על דברי רב! ודוחים: \u0003ומי אלימא ממתניתין\u0004 \u0005[והאם תקיפה\u0006 ברייתא זו \u0005ממשנתנו]?!\u0006 \u0003דאוקימנא\u0004 \u0005[שהעמדנו,\u0006 הסברנו אותה\u0005]\u0006 שכוונתה להחמיר \u0003שלא יטלטל שתי אמות בגג זה ושתי אמות בגג זה, הכי נמי\u0004 \u0005[כך גם כן]\u0006 את הברייתא נפרש שבאה ללמדנו שלא יטלטל \u0003שתי אמות בגג זה ושתי אמות בגג זה.\u0004","\u0003אמר רב יוסף\u0004 לאחר שחלה ונשכח ממנו תלמודו: \u0003לא שמיע לי הא שמעתא\u0004 \u0005[שמעתי הלכה זו]\u0006 שאמר שמואל בענין מחיצות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: את\u0004 \u0005[אתה]\u0006 \u0003אמרת\u0004 אותה \u0003ניהלן\u0004 \u0005[לנו],\u0006 \u0003ואהא\u0004 \u0005[ועל\u0006 דבר \u0005זה]\u0006 \u0003אמרת\u0004 אותה \u0003ניהלן\u0004 \u0005[לנו]:\u0006 שנינו כי \u0003גג גדול הסמוך לקטן — הגדול מותר\u0004 משום שניכרים מחיצותיו לצידי הקטן ואינו פרוץ אליו במלואו, \u0003והקטן אסור,\u0004 שהוא פרוץ בכל רוחבו לגג השני האסור לו.","\u0003ואמרת לן עלה\u0004 \u0005[לנו עליה,\u0006 על כך\u0005]:\u0006 \u0003אמר רב יהודה אמר שמואל: לא שנו\u0004 \u0005[נשנתה]\u0006 הלכה זו \u0003אלא שיש דיורין על\u0004 גג \u0003זה ודיורין על\u0004 גג \u0003זה, דהויא לה הא\u0004 \u0005[ונעשית לה זו\u0006 גגו\u0005]\u0006 של \u0003קטן מחיצה נדרסת,\u0004 שהרי עוברים דרכה מאחת לשניה, והריהו כחצירות שנפרצו זו לזו.","\u0003אבל\u0004 אם \u0003אין דיורין על זה ועל זה — שניהן מותרין,\u0004 ומסתמא טעמו משום שמחיצות הבתים שלמטה נחשבות כמגיעות מעל גגות הבתים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: עכשיו אני נזכר במה שהיה, \u0003אנא הכי אמרי לכו\u0004 \u0005[אני כך אמרתי לכם]:\u0006 \u0003לא שנו אלא שיש מחיצה על זה ומחיצה על זה\u0004 חוץ ממקום חיבורם, ש\u0003גדול מישתרי בגיפופי\u0004 \u0005[מותר על ידי שרידי\u0006 הגדר\u0005],\u0006 שהרי מצד הגדול נראים שרידי הגדר. \u0003ו\u0004ה\u0003קטן נפרץ במלואו,\u0004 ולכן נאסר. \u0003אבל אין מחיצה לא על זה ולא על זה — שניהן אסורין.\u0004","והקשה לו אביי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003דיורין אמרת לן\u0004 \u0005[לנו]\u0006 ודבר זה זכור לי בבירור! ענה לו: \u0003אי אמרי לכו דיורין, הכי אמרי לכו\u0004 \u0005[אם אמרתי לכם\u0006 והזכרתי \u0005דיורים, כך אמרתי לכם]:\u0006 \u0003לא שנו\u0004 שהקטן אסור כלל בטלטול \u0003אלא שיש מחיצה ראויה לדירה על זה ומחצה ראויה לדירה על זה,\u0004 ש\u0003גדול מישתרי בגיפופי\u0004 \u0005[מותר על ידי שרידי\u0006 הגדר\u0005]\u0006 \u0003ו\u0004ה\u0003קטן נפרץ במלואו.\u0004","\u0003אבל יש מחיצה ראויה לדירה על הגדול, ואין ראויה לדירה על הקטן — אפילו קטן שרי\u0004 \u0005[מותר]\u0006 \u0003לבני גדול. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון\u0004 ש\u0003לא עבוד\u0004 \u0005[עשו]\u0006 \u0003מחיצה גמורה משמע שסלוקי סליקו נפשייהו מהכא\u0004 \u0005[סלקו עצמם מכאן]\u0006 ונתנו רשותם לבני הגג הגדול.","\u0003כהא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר רב נחמן: עשה סולם קבוע לגגו — הותר בכל הגגין כולן.\u0004 ואילו שאר בעלי הגגות, כיון שלא עשו סולם, סימן שויתרו על רשות גגם לזה שעשה סולם קבוע.","\u0003אמר אביי:\u0004 מי ש\u0003בנה עלייה על גבי ביתו ועשה לפניה\u0004 כלומר, לפני פתחה \u0003דקה\u0004 (מחיצה) גבוהה \u0003ארבע\u0004 אמות לפתחה לצד הגגות — \u0003הותר בכל הגגין כולן,\u0004 כי על ידי עשיית המחיצה הוכיח שקובע מקום דירתו על הגג. ושאר גגות שלא עשו כך, בטלים לגגו של זה.","\u0003אמר רבא: פעמים שהדקה לאיסור,\u0004 שייתכן שהמחיצה תעשה דוקא צד איסור לדעת כולם, \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 מקרה כזה — \u0003כגון דעבידא להדי תרביצא דביתיה\u0004 \u0005[שעשויה\u0006 שתהא פתוחה \u0005לצד גינת ביתו]\u0006 ולצד הגגות הניח סתום, \u0003דאמר\u0004 \u0005[שהוא אומר]\u0006 שמובן על ידי מה שעשה"],["\u0003לנטורי תרביצא\u0004 \u0005[לשמור את הגינה ]\u0006 \u0003הוא דעבידא\u0004 \u0005[שעשויה],\u0006 ואין לה כל קשר עם הגגות, ובכך סילק עצמו מהגגות.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 לשיטת רב שאין לטלטל בין הגגות, אלא בארבע אמות של כל גג בפני עצמו, אם כן לטלטל \u0003שתי אמות בגג ושתי אמות בעמוד\u0004 הגבוה עשרה טפחים ורחב ארבעה הסמוך לגג \u0003מהו\u0004 הדין? \u0003אמר רבה: מאי קא מיבעיא ליה\u0004 \u0005[מה הבעיה המסופקת לו],\u0006 \u0003כרמלית ורשות היחיד קא מיבעיא ליה\u0004 \u0005[נשאלה לו]?\u0006 שהרי הגג דינו ככרמלית, והעמוד הוא רשות היחיד גמורה, ובכגון זה ודאי שאסור.","ומסבירים כי זו ודאי אינה שאלה, אלא \u0003ורמי בר חמא אגב חורפיה\u0004 \u0005[מתוך חריפותו]\u0006 \u0003לא עיין בה\u0004 בשאלה די הצורך ולא העמיד את פרטיה כראוי, \u0003אלא הכי קמיבעיא ליה\u0004 \u0005[כך נשאלה לו]:\u0006 \u0003שתי אמות בגג\u0004 של אחד \u0003ושתי אמות ב\u0004גג משופע של \u0003אכסדרה\u0004 השייכת לאחר \u0003מהו,\u0004","\u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003כיון\u0004 ש\u0003לא האי חזי\u0004 \u0005[זה\u0006 \u0003הגג\u0004 \u0005ראוי]\u0006 \u0003לדירה ולא האי חזי\u0004 \u0005[זה\u0006 גג האכסדרה \u0005ראוי]\u0006 \u0003לדירה חדא רשותא\u0004 \u0005[רשות אחת]\u0006 \u0003היא,\u0004 ומותר. \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיון\u0004 ש\u0003מגג לגג אסיר\u0004 \u0005[אסור],\u0006 \u0003מגג לאכסדרה נמי אסיר\u0004 \u0005[גם כן אסור],\u0006 שאף היא רשות מיוחדת לעצמה.","בדומה לזה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב ביבי בר אביי: שתי אמות בגג\u0004 של אחד, \u0003ושתי אמות בחורבה\u0004 של אחר הפתוחה לרשות הרבים, \u0003מהו,\u0004 המותר לטלטל בשתיהם יחד עד ארבע אמות?","\u0003אמר רב כהנא: לאו היינו\u0004 \u0005[האם לא זו\u0006 בדיוק\u0005]\u0006 שאלת \u0003רמי בר חמא\u0004 באכסדרה?! \u0003אמר רב ביבי בר אביי: וכי מאחר אתאי ונצאי\u0004 \u0005[אחרתי ובאתי לריב]\u0006 (מאירי), כלומר, האם לדעתך באתי סתם לחזור ולהתערב בשאלת אחרים? אין הדבר כן, והשאלות אינן זהות, \u0003אכסדרה לא חזיא\u0004 \u0005[ראויה]\u0006 \u0003לדירה, וחורבא חזיא\u0004 \u0005[ראויה]\u0006 \u0003לדירה,\u0004 ושמא דינה שונה.","ותוהים: \u0003וכי מאחר דחזיא\u0004 \u0005[שראויה\u0006 היא\u0005]\u0006 \u0003לדירה מאי קא מיבעיא ליה\u0004 \u0005[מה נסתפק לו]\u0006 הלוא הם כשני גגות סתם! ומשיבים: את שאלתו יש להבין בדרך \u0003אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר קאמר\u0004 \u0005[אמר],\u0006 וכך שאל: \u0003אם תימצי לומר\u0004 אם תגיע למסקנה כי \u0003אכסדרה לא חזיא\u0004 \u0005[ראויה]\u0006 \u0003לדירה\u0004 ולכן מותרת, אבל \u0003חורבה חזיא\u0004 \u0005[ראויה]\u0006 \u0003לדירה,\u0004 ולכן גגה נחשב כגג ממש וצריכה תיקון כלשהו כדי להתירה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר שאינו כן, שהרי \u0003השתא מיהא לית\u0004 \u0005[עכשיו בכל אופן אין]\u0006 \u0003בה\u0004 בחורבה \u0003דיורין,\u0004 ואין היא כגג. לשתי השאלות לא נמצאה תשובה והושארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה]","ודנים בשאלה אחרת, כשם שנחלקו רב ושמואל בדברי חכמים כך נחלקו לענין \u0003גגין השוין\u0004 בגובהם זה לזה \u0003ל\u0004שיטת \u0003ר' מאיר, וגג יחידי\u0004 שאין אחרים סביבו \u0003ל\u0004שיטת \u0003רבנן\u0004 מה דינם? \u0003רב אמר: מותר לטלטל בכולו, ושמואל אמר: אין מטלטלין בו אלא בארבע\u0004 אמות.","ומפרשים ומפרטים את השיטות, \u0003רב אמר: מותר לטלטל בכולו,\u0004 ולכאורה הרי \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רב\u0004 על דברי \u0003רב\u0004 שאמר (לעיל עירובין עט,א) בגגות השוים לשיטת חכמים אין לטלטל ארבע אמות! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בגג שבין שאר גגות \u0003לא מינכרא מחיצתא\u0004 \u0005[ניכרות המחיצות],\u0006 שכן המחיצות הן בתוך הבתים ואין להחשיבן. \u0003הכא מינכרא מחיצתא\u0004 \u0005[כאן ניכרות המחיצות],\u0006 ונראה היטב גבולו של הבית או קבוצת הבתים השוים, ואומרים שהמחיצות כאילו עולות מעל לגובה שפת הגג ותוחמות אותו.","\u0003ושמואל אמר: אין מטלטלין בו אלא בארבע אמות,\u0004 ולכאורה הרי \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003שמואל\u0004 על דברי \u0003שמואל\u0004 שבגגות השוים, לדברי חכמים התיר לטלטל! ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003לא הוי\u0004 \u0005[היה]\u0006 שטח הגג \u0003יותר מבית סאתים. הכא\u0004 \u0005[כאן]\u0006 מדובר ש\u0003הוי\u0004 \u0005[היה]\u0006 \u0003יותר מבית סאתים, והני\u0004 \u0005[ואלה]\u0006 ה\u0003מחיצות\u0004 שיש לו לגג שהן כתלי הבית החיצונות לצורך \u0003מטה עבידן\u0004 \u0005[עשויות],\u0006 שנועדו להיות מחיצות הדירה עצמה, אבל לצורך \u0003מעלה לא עבידן\u0004 \u0005[עשויות].\u0006 ואם כן, אף שדינן כמחיצות, הריהן מחיצות שאינן אלא \u0003כקרפף יתר מבית סאתים שלא הוקף\u0004 מתחילה לצורך \u0003דירה\u0004 בו, \u0003ו\u0004כלל הוא: ש\u0003כל קרפף יותר מבית סאתים שלא הוקף לדירה — אין מטלטלין בו אלא בארבע\u0004 אמות.","ועוד \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בענין \u0003ספינה\u0004 גדולה. \u0003רב אמר: מותר לטלטל בכולה\u0004 שכולה רשות אחת, \u0003ושמואל אמר: אין מטלטלין בה אלא בארבע\u0004 אמות. ומפרטים, \u0003רב אמר: מותר לטלטל בכולה\u0004"],["\u0003דהא איכא מחיצתא\u0004 \u0005[שהרי יש מחיצות].\u0006 \u0003ושמואל אמר: אין מטלטלין בה אלא בארבע אמות,\u0004 וטעמו כי \u0003מחיצות\u0004 הספינה \u0003להבריח מים\u0004 הן \u0003עשויות,\u0004 ולא כדי לשמש בה לדירה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חייא בר יוסף לשמואל: הילכתא כוותך\u0004 \u0005[הלכה כמותך]\u0006 \u0003או הילכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הילכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב,\u0004 שטעמו מסתבר.","\u0003אמר רב גידל אמר רב חייא בר יוסף: ומודה רב שאם כפאה\u0004 את הספינה \u0003על פיה\u0004 וגבוהה יותר מעשרה טפחים, \u0003שאין מטלטלין בה אלא בארבע אמות.\u0004 ושואלים: \u0003כפאה, למאי\u0004 \u0005[למה,\u0006 לאיזה צורך\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכפאה על מנת \u0003לדור תחתיה,\u0004 אם כן \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 היא \u0003מגג יחידי?\u0004","והרי עתה דינה לכל דבר כבית ומותר לטלטל בכולה, \u0003אלא שכפאה\u0004 כדי \u0003לזופתה,\u0004 לצפות את קרקעיתה מחדש בזפת. שודאי אין גבה של הספינה עשוי לדיור כלל, ואין המחיצות דרושות לצורך דיור כל זמן שהפוכה לצורך זה.","\u0003רב אשי מתני לה\u0004 \u0005[היה שונה אותה]\u0006 כאמור לענין \u0003ספינה, ורב אחא בן רבא מתני לה\u0004 \u0005[היה שונה אותה]\u0006 הסכמתו זו של שמואל לדברי רב החולק עליו (ריטב\"א) לענין \u0003אכסדרה. דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בדבר \u0003אכסדרה בבקעה,\u0004 שלאכסדרה אין מחיצות בכלל אלא תקרה, ואם מצויה היא בבקעה (שדה) שדינה ככרמלית יש לדון מה דינה לענין טלטול. \u0003רב אמר: מותר לטלטל\u0004 באכסדרה \u0003כולה. ושמואל אמר: אין מטלטלין בה אלא בארבע\u0004 אמות.","ומפרטים, \u0003רב אמר: מותר לטלטל בכולה,\u0004 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003פי תקרה יורד וסותם,\u0004 שאנו מחשיבים את תקרת האכסדרה כאילו הקצה יורד עד למטה ויוצר מחיצה לאכסדרה. ונמצאת כאילו סגורה מכל צד כרשות היחיד גמורה. \u0003ושמואל אמר: אין מטלטלין בה אלא בארבע,\u0004 כי \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003פי תקרה יורד וסותם.\u0004","ושואלים לעיקרי השיטות: \u0003ורב אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' מאיר,\u0004 שלדעתו מותר לטלטל בין גגות השוים בכל שיעור שהוא, אם כן \u0003ליטלטלי\u0004 \u0005[שיטלטלו]\u0006 \u0003מגג לחצר?!\u0004 ומשיבים: שר' מאיר אוסר זאת מטעם \u0003גזירה משום\u0004 הסברו של \u0003רב יצחק בר אבדימי\u0004 שהיה אומר בשם ר' מאיר שתי רשויות הנבדלות זו מזו בגובה מעשרה טפחים ומעלה, אף שהן רשות אחת מדין תורה — אין מטלטלים מזו לזו, שמא יבואו לטלטל בכגון זו אף ברשות הרבים.","ועוד שואלים: \u0003ושמואל אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים]\u0006 גג יתר מבית סאתים דינו ככרמלית, אם כן \u0003ניטלטל מגג\u0004 יחידי \u0003לקרפף\u0004 שתי אמות בכל אחד, שהרי אף הקרפף ככרמלית הוא. \u0003אמר רבא בר עולא: גזירה שמא יפחת הגג\u0004 עד פחות מבית סאתים, ויהא דינו כרשות היחיד, וייאסר הטלטול ממנו לקרפף.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003מקרפף לקרפף נמי\u0004 \u0005[גם כן]\u0006 \u0003לא יטלטל, דילמא מיפחית ואתי לטלטולי\u0004 \u0005[שמא יפחת\u0006 שיעורו \u0005ויבוא לטלטל]?\u0006 ומשיבים: \u0003התם, אי מיפחית, מינכרא ליה מילתא\u0004 \u0005[שם, אם נפחת\u0006 השיעור, \u0005ניכר לו הדבר]\u0006 שהכל רואים שנפחתו מחיצות הקרפף. \u0003הכא, אי מיפחית, לא מינכרא מילתא\u0004 \u0005[כאן, אם יפחת\u0006 השיעור, \u0005אין הדבר ניכר]\u0006 שהרי אין לגג עצמו מחיצות.","\u0003אמר רב יהודה: כשתמצא לומר\u0004 ותמצה את השיטות בנושא זה הרי \u0003לדברי ר' מאיר גגין רשות לעצמן\u0004 ומטלטלים מגג של אחד לשל אחר, וכן \u0003חצרות רשות לעצמן\u0004 ומטלטלים מחצר של אחד לשל אחר."],["\u0003קרפיפות\u0004 ואפילו הן של שני אנשים \u0003רשות לעצמן\u0004 ויכולים לטלטל מאחת לשניה. \u0003לדברי חכמים: גגין וחצירות\u0004 של רבים \u0003רשות אחת\u0004 הם, ואילו \u0003קרפיפות\u0004 אפילו של שנים \u0003רשות אחת הן. לדברי ר' שמעון: כולן רשות אחת הן\u0004 ומטלטלים מאחד לאחר.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב, תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב יהודה. תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב\u0004 שבגגות אף השווים בגובהם אין מטלטלים אלא בארבע אמות בלבד, ושלא כשיטת שמואל: \u0003כל גגות העיר רשות אחת הן, ואסור להעלות ולהוריד מן הגגין לחצר ומן החצר לגגין. וכלים ששבתו בחצר — מותר לטלטלן בחצר,\u0004 אף על פי שלא עירבוה, וכן ממנה לחצירות אחרות. וששבתו \u0003בגגין — מותר לטלטלן בגגין, ובלבד שלא יהא גג גבוה עשרה\u0004 טפחים \u0003או נמוך עשרה\u0004 טפחים מחבירו, אלו \u0003דברי ר' מאיר. וחכמים אומרים: כל אחד ואחד רשות לעצמו, ואין מטלטלין בו אלא בארבע\u0004 אמות בלבד.","וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב יהודה\u0004 בהבנת דברי ר' שמעון, \u0003אמר רבי: כשהיינו לומדים תורה אצל ר' שמעון בתקוע, היינו מעלין שמן\u0004 לסוך \u0003ואלונטית\u0004 \u0005[מגבת]\u0006 להתנגב \u0003מגג לגג, ומגג לחצר, ומחצר לחצר, ומחצר לקרפף, ומקרפף לקרפף אחר\u0004 כדי שלא לטלטל במקום האסור, \u0003עד שהיינו מגיעין אצל המעין שהיינו רוחצין בו.\u0004","ובדומה לכך \u0003אמר ר' יהודה: מעשה בשעת הסכנה\u0004 שגזרו על קיום המצוות, \u0003והיינו מעלין ספר תורה מחצר לגג, ומגג לחצר, ומחצר לקרפף לקרות בו.\u0004","\u0003אמרו לו\u0004 חכמים: שאין להביא מכאן הוכחה, כי \u0003אין שעת הסכנה ראיה,\u0004 ובשעת סכנה הקלו לטלטל אף במקום האסור מדברי חכמים.","במשנה למדנו ש\u0003ר' שמעון אומר: אחד גגין\u0004 ואחד חצירות וקרפיפות רשות אחת הם לכלים ששבתו בתוכם, אבל לא לאלו ששבתו בתוך הבית ויצאו לחצר.","\u0003אמר רב: הלכה כר' שמעון, והוא שלא עירבו\u0004 בני החצר כל אחד לעצמו, שאז אסור להם להוציא חפצים מבתיהם אל החצר. \u0003אבל עירבו\u0004 כל אחד לעצמו אבל לא בין החצירות \u0003— לא, דגזרינן דילמא אתי לאפוקי מאני\u0004 \u0005[שגוזרים אנו שמא יבוא להוציא את החפצים]\u0006 שב\u0003בתים לחצר.\u0004 שהרי מותר להם להוציאם מלכתחילה מהבתים לחצר, ואחר כך יוציאום לחצר אחרת שלא עירבה עמה, ובאופן זה אין מי שמתיר.","\u0003ושמואל אמר: בין עירבו בין שלא עירבו. וכן אמר ר' יוחנן: מי לחשך\u0004 (לחש לך, גילה לך) שיש הבדל \u0003בין עירבו ובין שלא עירבו?\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: לשמואל ולר' יוחנן,\u0004 מעתה \u0003יאמרו\u0004 אנשים: \u0003שני כלים\u0004 מצויים \u0003בחצר אחת,\u0004 זה ששבת בחצר וזה ששבת בבית, זה ששבת בחצר \u0003מותר\u0004 בטלטול לחצר אחרת \u0003וזה\u0004 ששבת בבית \u0003אסור,\u0004 ויבואו להחליף ביניהם!","ומשיבים: \u0003ר' שמעון\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003לא גזר\u0004 ולא חשש לכגון זה. שכן שנינו, \u0003אמר ר' שמעון: למה הדבר דומה, לשלש חצירות הפתוחות זו לזו ופתוחות לרשות הרבים, ועירבו שתי החיצונות עם האמצעית\u0004 כל אחד לחוד — \u0003היא\u0004 החצר האמצעית, \u0003מותרת עמהן והן מותרות עמה, ושתי החיצונות אסורין זו עם זו.\u0004","\u0003ולא גזר דילמא אתי לאפוקי מאני דהא חצר להא חצר\u0004 \u0005[שמא יבוא להוציא כלים של חצר\u0006 קיצונית \u0005זו לחצר\u0006 קיצונית \u0005זו],\u0006 אף שהחפצים מצויים שניהם בחצר האמצעית, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003לא גזרינן דילמא אתי לאפוקי מאני\u0004 \u0005[גוזרים אנו שמא יבוא להוציא כלים]\u0006 של ה\u0003בתים לחצר.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת, ר' שמעון אומר: אחד גגות אחד חצירות ואחד קרפיפות — רשות אחת הן לכלים ששבתו בתוכן, ולא לכלים ששבתו בתוך הבית. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003עירבו\u0004 הדרים בחצר — \u0003היינו דמשכחת לה מאני\u0004 \u0005[זהו\u0006 האופן \u0005שמוצא אתה כלים]\u0006 של ה\u0003בתים בחצר,\u0004 ועל זה אמר שכיון ששבתו בבית, אם הוציאום לחצר, אסור להוציאם ממנה לחצר אחרת,","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר \u0003בשלא עירבו — היכי משכחת לה מאני\u0004 \u0005[כיצד מוצא אתה כלים]\u0006 של ה\u0003בתים בחצר?\u0004 וקשה לרב! \u0003הוא מותיב לה\u0004 \u0005[מקשה אותה\u0006 את הקושיה הזו\u0005]\u0006 \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[מתרץ אותה]:\u0006 \u0003בכומתא וסודרא\u0004 \u0005[בכובע וסודר]\u0006 שאדם לבשם בבית ויצא לבוש לחצר והניחם שם, כך שיתכן שיהיו חפצי הבית בחצר גם כשלא עירבו."],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה בענין זה, ששנינו: \u0003אנשי חצר ואנשי מרפסת ששכחו ולא עירבו, כל\u0004 דבר \u0003שגבוה עשרה טפחים\u0004 — שייך לענין שימוש בו בשבת \u0003למרפסת. פחות מכאן — לחצר. במה דברים אמורים\u0004 שאסורים בני החצר בטלטול למרפסת ולהיפך — \u0003שהיו אלו\u0004 בחצר \u0003של רבים, ואלו\u0004 במרפסת \u0003של רבים, ועירבו אלו לעצמן ואלו לעצמן. או\u0004 שהיו החצר והמרפסת \u0003של יחידים שאין צריכים לערב\u0004 בינם לבין עצמם.","\u0003אבל היו\u0004 החצר והמרפסת \u0003של רבים, ושכחו ולא עירבו\u0004 בתוך חצרם או בתוך המרפסת שלהם — הרי \u0003גג וחצר ואכסדרה ומרפסת כולן רשות אחת הן,\u0004 ומותר לטלטל את הכלים ששבתו בתוכם בין כולן.","ומלשון זו נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 כש\u0003לא עירבו, הא\u0004 \u0005[הרי]\u0006 אם \u0003עירבו — לא,\u0004 וסיוע בכך לדברי רב וקשה לשמואל! ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שלדעתם הגגות והחצירות רשות אחת הם, ולא כשיטת ר' שמעון.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 כך, שכן \u0003לא קתני\u0004 \u0005[שנינו]\u0006 שם בין הדוגמאות גם \u0003קרפף ומבוי\u0004 כשיטת ר' שמעון, אלא רק בגג וחצר, וכדברי חכמים. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן היא ההבנה הנכונה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה אחרת לענין זה ממה ששנינו: \u0003חמש חצירות הפתוחות זו לזו ופתוחות למבוי, ושכחו כולם ולא עירבו — אסור להכניס ולהוציא מחצר למבוי, ומן המבוי לחצר. ו\u0004אילו \u0003כלים ששבתו בחצר — מותר לטלטלן בחצר,\u0004 אבל \u0003במבוי אסור.\u0004","\u0003ור' שמעון מתיר. שהיה ר' שמעון אומר: כל זמן\u0004 שהחצירות של \u0003רבים, ושכחו ולא עירבו, הרי גג וחצר ואכסדרה ומרפסת וקרפף ומבוי — כולן רשות אחת הן,\u0004 שהרי כולם רשות היחיד מבחינת הגדרת הרשויות, ומותר לטלטל מזו לזו.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 ש\u0003לא עירבו, הא\u0004 \u0005[הרי]\u0006 אם \u0003עירבו — לא,\u0004 וקשה לשמואל! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"לא עירבו\"\u0004 — יש להבין: \u0003לא עירבו חצירות בהדי הדדי\u0004 \u0005[זו עם זו],\u0006 ואולם \u0003הא\u0004 \u0005[הרי]\u0006 \u0003חצר ובתים שבתוכה — עירבו,\u0004 ובכל זאת מותר לטלטל, וכשמואל.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"לא עירבו\" קתני\u0004 \u0005[שנינו],\u0006 משמע שלא עירבו כלל, ולא שעירבו במקצת! ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא עירבו\"\u0004 — הכוונה: ש\u0003לא נשתתפו,\u0004 שלא עשו החצירות הפונות למבוי עירוב במבוי.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003ר' שמעון לדבריהם דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם]\u0006 ולא מיצה את כל אפשרויות ההיתר כשיטת עצמו, וכך יש להבין את דבריו בהשלמתם: \u0003לדידי\u0004 \u0005[לי עצמי,\u0006 לשיטתי] \u0003לא שנא\u0004 \u0005[שונה]\u0006 כש\u0003עירבו, לא שנא\u0004 \u0005[שונה]\u0006 כש\u0003לא עירבו. אלא לדידכו\u0004 \u0005[לעצמכם,\u0006 לשיטתכם\u0005],\u0006 \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת דהיכא\u0004 \u0005[לפחות היכן,\u0006 במקרה\u0005]\u0006 כש\u0003לא עירבו רשות אחת היא.\u0004","\u0003ואמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 \u0003לא,\u0004 שאף על פי שמסכימים אנו לדבריך בגג, חצר, אכסדרא ומרפסת — בקרפף ומבוי איננו מסכימים, אלא \u0003שתי רשויות הן\u0004 ואסורות בטלטול מכאן לכאן.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 בקטע הקודם נאמר שכלים ששבתו בחצר מותר לטלטלם בחצר \u0003ובמבוי אסור.\u0004 ושואלים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שדבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004שיטתו של \u0003ר' זירא אמר רב,\u0004 ש\u0003אמר ר' זירא אמר רב: מבוי שלא נשתתפו בו — אין מטלטלין\u0004 בו \u0003אלא בארבע אמות.\u0004 ודוחים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003למבוי — אסור\u0004 לטלטל מן החצר, אבל חפצים שבמבוי עצמו — מותר.","ומקשים: אם כן, \u0003היינו רישא\u0004 \u0005[\u0006הרי \u0005זו ההתחלה\u0006 עצמה\u0005]\u0006 ואין זה מתקבל על הדעת שיחזור וישנה אותם דברים! ומשיבים: \u0003משנה יתירא איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 שאם לא כן, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כך: \u0003כי פליגי רבנן עליה\u0004 \u0005[כאשר נחלקו חכמים עליו]\u0006 על \u0003ר' שמעון — הני מילי היכא\u0004 \u0005[דברים אלה\u0006 נאמרו \u0005במקום]\u0006 ש\u0003עירבו, אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא עירבו — מודו ליה\u0004 \u0005[מודים לו]\u0006 שהכל רשות אחת ומותר לטלטל, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינם מודים לו כלל, ולמבוי אסור לטלטל אפילו כשלא עירבו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004"],["\u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שהלכה כר' שמעון? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: הלכה כסתם משנה. ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003כותל שבין שתי חצירות,\u0004 אם היה הכותל \u0003גבוה עשרה\u0004 טפחים \u0003ורוחב ארבעה — מערבין שנים\u0004 עירוב בכל חצר לחוד, \u0003ואין מערבין אחד. היו בראשו פירות — אלו עולין מכאן ואוכלין, ואלו עולין מכאן ואוכלין, ובלבד שלא יורידו\u0004 פירות מראשו \u0003למטה\u0004 לחצירם! ולשיטת ר' יוחנן מדוע לא יורידו למטה? והרי כל החצירות רשות אחת הן!","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"למטה\"\u0004 — כוונתו: \u0003למטה לבתים,\u0004 אבל לחצירות אמנם מותר. ומקשים: \u0003והא תני\u0004 \u0005[והרי\u0006 במפורש \u0005שנה]\u0006 \u0003ר' חייא\u0004 באחת מתוספתותיו: \u0003ובלבד שלא יהא זה עומד במקומו\u0004 למטה בחצר זו \u0003ואוכל, וזה עומד במקומו ואוכל!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין להוכיח מברייתא זו של ר' חייא לענין פירושה של המשנה. כי אם \u0003רבי לא שנאה\u0004 במפורש בצורה זו, \u0003ר' חייא\u0004 תלמידו \u0003מנין לו?\u0004 ואם אין הדבר נובע מן המשנה עצמה, אין לדחוק ולפרש בה בהתאם לאמור בתוספתא.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר: \u0003שתי חצירות\u0004 שהיתה \u0003חורבה אחת ביניהן,\u0004 חצר \u0003אחת עירבה\u0004 בינה לבין עצמה וכלי הבתים בתוכה, וחצר \u0003אחת לא עירבה, אמר רב הונא: נותנין אותה,\u0004 את החורבה לענין זכות שימוש בשבת \u0003לזו שלא עירבה, אבל לשעירבה — לא\u0004 תהא רשאית להשתמש בה. וטעם הדבר, \u0003דילמא אתי לאפוקי מאני\u0004 \u0005[שמא יבוא להוציא כלי]\u0006 ה\u0003בתים לחורבה,\u0004 והרי החורבה לא עירבה ואסורה הוצאה זו. מה שאין כן בחצר שלא עירבה, שכיון שאיננה יכולה להוציא חפצים מן הבית לחצר הרי אין איסור להוציא חפצים מהחצר עצמה לחורבה, ואף אין מקום לחשש.","\u0003וחייא בר רב אמר:\u0004 החורבה הזו שייכת אף \u0003ל\u0004חצר \u0003שעירבה,\u0004 משום כך \u0003שתיהן אסורות. ואם תאמר\u0004 שמשום כך \u0003שתיהן\u0004 תהיינה \u0003מותרות\u0004 בחורבה, אין הדבר מתקבל, שאם כן \u0003מפני מה אין נותנין חצר שלא עירבה לחצר שעירבה?\u0004 שאם אומרים שאין כלל מקום לחשוש מותר יהא תמיד לבני חצר שעירבה לטלטל מחצרם גם בחצר האחרת שלא עירבה!","ודוחים: \u0003התם\u0004 \u0005[שם],\u0006 בחצירות \u0003כיון דמנטרי מאני\u0004 \u0005[שנשמרים כלי]\u0006 ה\u0003בתים בחצר\u0004, מוציאים הם כלים רבים לחצר ויש חשש שמא \u0003אתי לאפוקי\u0004 \u0005[יבוא להוציאם]\u0006 מן הבית לחצר על ידי שיחליפם בטעות עם אלו שהיו כבר בחצר. \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003בחורבה כיון\u0004 ש\u0003לא מינטרי מאני\u0004 \u0005[נשמרים כלי]\u0006 ה\u0003חצר בחורבה, לא אתי לאפוקי\u0004 \u0005[יבוא להוציאם],\u0006 ולכן אפשר להתיר את שתיהן בחורבה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 גרסה אחרת, \u0003חייא בר רב אמר:\u0004 שהחורבה שייכת בשימוש \u0003אף לשעירבה, ושתיהן\u0004 שתי החצירות \u0003מותרות\u0004 לטלטל בחורבה. \u0003ואם תאמר: שתיהן אסורות,\u0004 ותרצה להוכיח כפי שהוכחנו קודם — \u0003לפי שאין נותנין חצר שלא עירבה לחצר שעירבה,\u0004 אפשר לדחות את הראיה: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דמינטרי מאני\u0004 \u0005[שנשמרים כלי]\u0006 ה\u0003בתים בחצר, לא שרו בהו רבנן\u0004 \u0005[התירו בהם חכמים]\u0006 שיש לחשוש שמא \u0003אתי לאפוקי\u0004 \u0005[יבוא להוציאם],\u0006 \u0003אבל בחורבה לא מנטרי\u0004 \u0005[נשמרים],\u0006 ואין לחשוש.","\u0003גג גדול סמוך לקטן\u0004 ואין הפירצה שביניהם רחבה מעשר אמות — \u0003הגדול מותר\u0004 בהכנסת כלים אליו מהדירה שתחתיו ולטלטלם בו, \u0003והקטן אסור.\u0004 וכן \u0003חצר גדולה\u0004 שעירבה לעצמה ו\u0003נפרצה לקטנה\u0004 פחות מעשר אמות, עד שכל כותלה של החצר הקטנה פרוץ — החצר ה\u0003גדולה מותרת, וקטנה אסורה.\u0004 והטעם, \u0003מפני שהיא כפתחה של גדולה,\u0004 שכאשר מסתכלים מצד החצר הגדולה רואים שיש בה אמנם פירצה, אבל יש מחיצות משני צידי הפרצה. ואילו מצד החצר הקטנה, הרי כל הכותל כולו פרוץ, ואין כל חציצה בינה ובין החצר הגדולה.","ושואלים: \u0003למה לי למתני תרתי\u0004 \u0005[לשנות שתיים]\u0006 כלומר, לחזור על אותה הלכה גם בגג וגם בחצר? והלוא לכאורה זהים הדברים!","ומשיבים: \u0003ל\u0004שיטת \u0003רב\u0004 הסובר שאין לטלטל בגג אלא אם כן יש לדירה שתחתיו מחיצות, שמדין \"גוד אסיק\" הריהן כאילו תוחמות אף את הגג, \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003גג דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003חצר,\u0004 שנלמד מדין חצר לדין גג; \u0003מה חצר מנכרא מחיצתא\u0004 \u0005[שניכרת מחיצתה],\u0006 \u0003אף גג נמי מנכרא מחיצתא\u0004 \u0005[גם כן\u0006 צריך שתהיה \u0005ניכרת מחיצתו],\u0006 כלומר, שתהיינה מחיצות הבית שוות לשפת הגג.","\u0003ול\u0004פי שיטת \u0003שמואל\u0004 שלדבריו אין צריך שתהיינה המחיצות ניכרות, יש להבין להיפך, ששנה \u0003גג דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003חצר; מה חצר, דקא דרסי לה\u0004 \u0005[שדורסים אותה]\u0006 \u0003רבים\u0004 ומשתמשים בה, \u0003אף גג נמי\u0004 \u0005[גם כן]\u0006 צריך שיהיה כזה \u0003דקא דרסי ליה\u0004 \u0005[שדורסים בו]\u0006 \u0003רבים.\u0004 ומטעם זה דריסת הרגל מבטל את החציצה בין הגגות.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבה ור' זירא ורבה בר רב חנן, ויתיב\u0004 \u0005[וישב]\u0006 \u0003אביי גבייהו\u0004 \u0005[עמם],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[וישבו ואמרו]:\u0006 \u0003שמע מינה ממתניתין\u0004 \u0005[למד ממנה ממשנתנו]\u0006 כי \u0003דיורי גדולה בקטנה\u0004 כלומר, משמעות וכח הדיור של החצר הגדולה מתפשט אל הקטנה, אבל \u0003אין דיורי קטנה בגדולה.\u0004 שרואים את המצוי בקטנה כחלק מן המצוי בגדולה, אבל לא להיפך.","\u0003כיצד? היו גפנים\u0004 בחצר \u0003הגדולה — אסור לזרוע את הקטנה\u0004 בזרעים, מפני האיסור של זריעת כלאים בכרם, אפילו בריחוק ארבע אמות מן הגפנים. \u0003ואם זרע — זרעין אסורין,\u0004 שהרי החצר הקטנה נחשבת כחלק מן הגדולה וכפתח שלה. והגפנים שבחצר הגדולה אוסרות את זרעי החצר הקטנה."],["\u0003גפנים מותרין,\u0004 ואין הזרעים אוסרים את הגפנים, משום שאין דיורי קטנה בגדולה. ולהיפך, אם \u0003גפנים בקטנה — מותר לזרוע את הגדולה\u0004 לכתחילה בזרעים אפילו בלא הרחקת ארבע אמות, שאין הגפנים נחשבות כמצויות בחצר הגדולה, ואין כאן צד של איסור.","וכן אם היו שתי חצירות באופן זה והיתה \u0003אשה\u0004 יושבת בחצר ה\u0003גדולה\u0004 שלה, וזרק לה בעלה \u0003גט\u0004 אל החצר \u0003הקטנה\u0004 שאף היא שלה — \u0003מתגרשת\u0004 על ידי כך. כי כוח ישיבתה של החצר הגדולה כולל גם את החצר הקטנה. ואולם אם \u0003אשה ב\u0004חצר ה\u0003קטנה וגט בגדולה — אינה מתגרשת.\u0004","וכן בענין תפלה בציבור, היה \u0003צבור ב\u0004חצר ה\u0003גדולה, ושליח צבור\u0004 עומד \u0003בקטנה — יוצאין ידי חובתן\u0004 בתפילתו, משום שנחשב שהציבור מצוי גם בקטנה. אבל אם היה \u0003ציבור בקטנה, ושליח צבור בגדולה — אין יוצאין ידי חובתן.\u0004","וכן לגבי מנין: היו \u0003תשעה בגדולה ויחיד בקטנה — מצטרפין,\u0004 שהקטנה בטלה לגבי הגדולה. ונחשב היחיד שבה כמצוי בגדולה. \u0003תשעה בקטנה ואחד בגדולה — אין מצטרפין.\u0004","ועוד, אם היתה \u0003צואה בגדולה — אסור לקרות קריאת שמע בקטנה,\u0004 שנחשב הדבר כאילו היתה הצואה מצויה אף בתוך החצר הקטנה, ואסור לקרוא קריאת שמע כשיש צואה במקום. ואילו \u0003צואה בקטנה — מותר לקרות קריאת שמע בגדולה.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי: אם כן, מצינו מחיצה לאיסור.\u0004 שלפי הגדרות אלה נמצא שפעמים המחיצה עצמה גורמת לאסור דברים אשר בלי מחיצה היו נחשבים מרוחקים זה מזה. והדבר אינו מתקבל על הדעת! \u0003שאילמלי אין מחיצה\u0004 בין החצירות כלל ולא היו מובדלות והיו גפנים באחת מהן, דיו ש\u0003מרחיק ארבע אמות\u0004 מן הגפנים \u0003וזורע, ואילו השתא\u0004 \u0005[עכשיו]\u0006 \u0003אסורה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לאביי:\u0004 וכי \u0003לא מצינו מחיצה לאיסור?! והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חצר גדולה שנפרצה לקטנה — גדולה מותרת וקטנה אסורה, מפני שהיא כפתחה של גדולה.\u0004","\u0003ואילו השוה את גיפופיה\u0004 כלומר אילו היה עושה מחיצות בתוך החצר הגדולה שלא תבלוט עוד מן החצר הקטנה הרי \u0003גדולה נמי\u0004 \u0005[גם כן]\u0006 \u0003אסורה!\u0004 ונמצא כי על ידי בנין מחיצות נוספות אלה מוסיף איסור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 שאין להשוות, שכן \u0003התם\u0004 \u0005[שם]\u0006 תוספת זו שהוא עושה בחצר ומיישר את הגיפופים אינה נתפסת כעשיית מחיצה אלא להיפך \u0003סילוק מחיצות הוא,\u0004 שהרי מחיצות אלה נועדו רק לבטל את המחיצות הקודמות ואין הן עצמן משמשות גבול וחציצה בין שני מקומות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי: ולא מצינו מחיצה לאיסור? והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו אמוראים בבעיה:"],["\u0003סיכך\u0004 (הניח סכך) \u0003על גבי אכסדרה\u0004 (מרפסת) \u0003שיש לה פצימין,\u0004 שיש לה שתי דפנות כהילכתן האחת כנגד השניה, ואילו בשני הצדדים האחרים הפתוחים קבועות בזוויותיהם קורות המחזיקות את האכסדרה, ונעשות כעין פצימים = מזוזות, ונחשבות כסותמות את שני הקירות האחרים — הרי זו \u0003כשירה\u0004 לסוכה. \u0003ואילו השוה פצימיה\u0004 שעשה את המחיצות בתוך האכסדרה, לפנים מן הקורות — \u0003פסולה.\u0004 משמע שעשיית המחיצה, היא עצמה אוסרת!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לדידי\u0004 \u0005[לשיטתי]\u0006 לענין אכסדרה, אף בכגון זה הסוכה \u0003כשירה,\u0004 אלא אפילו \u0003לדידך\u0004 \u0005[לשיטתך]\u0006 \u0003סילוק מחיצות היא,\u0004 שהשואת הפצימין אינה אוסרת את הסוכה משום עשיית מחיצות בכלל, אלא משום שהיא מבטלת את המחיצות החיצונות של הסוכה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנן לאביי: ולא מצינו מחיצה לאיסור? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית שחציו מקורה\u0004 (בתקרה) \u0003וחציו אינו מקורה, גפנים כאן\u0004 בחלק הבית שתחת הקירוי — \u0003מותר לזרוע כאן,\u0004 בחלקו השני המגולה. שאנו אומרים כי קצה התקרה נחשב כיורד ויוצר מחיצה עד למטה בין חלקי הבית.","\u0003ואילו השוה את קירויו\u0004 שהשלים את התקרה על פני כל הבית כולו — \u0003אסור.\u0004 הרי שעשיית מחיצה (ובמקרה שלנו — גג) היא עצמה אוסרת! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אף \u0003התם\u0004 \u0005[שם]\u0006 \u0003סילוק מחיצות הוא,\u0004 שאין הכל נאסר בשל הקירוי אלא בשל ביטול המחיצה המדומה.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי ביד רב שמעיה בר זעירא\u0004 הוכחה אחרת באותו ענין: וכי \u0003לא מצינו מחיצה לאיסור? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003יש במחיצות הכרם\u0004 לענין כלאים צד \u0003להקל\u0004 וצד \u0003להחמיר, כיצד? כרם הנטוע עד עיקר\u0004 (בסיס) \u0003המחיצה — זורע מעיקר מחיצה ואילך\u0004 מן הצד השני. \u0003שאילו אין שם מחיצה\u0004 היה צריך להיות \u0003מרחיק ארבע אמות וזורע, וזה הוא מחיצות הכרם להקל.\u0004","\u0003ולהחמיר כיצד? היה\u0004 הכרם \u0003משוך\u0004 (מרוחק) \u0003מן הכותל אחת עשרה אמה — לא יביא זרע לשם\u0004 בין הכרם לכותל ויזרענו, \u0003שאילמלי אין מחיצה,\u0004 דיו ש\u0003מרחיק ארבע אמות\u0004 מן הגפנים \u0003וזורע. וזוהי מחיצות הכרם להחמיר.\u0004 הרי שיש מחיצה לאיסור!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לסברתך\u0005]\u0006 שאתה סבור שיש כאן קושיה, \u0003אותבן ממתניתין\u0004 \u0005[הקשה עלי ממשנה]\u0006 ולא מברייתא בלבד, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003קרחת הכרם\u0004 מתי נחשבת היא גדולה מספיק כדי להתיר לזרוע בה בריחוק ארבע אמות מן הגפנים? \u0003בית שמאי אומרים: עשרים וארבע אמות, ובית הלל אומרים: שש עשרה אמה. מחול הכרם\u0004 כלומר, המקום הפנוי שבין שורות הגפנים לגדר הכרם, \u0003בית שמאי אומרים שש עשרה אמה, ובית הלל אומרים שתים עשרה אמה.\u0004","\u0003ואיזו היא קרחת הכרם — כרם שחרב אמצעיתו. אם אין שם שש עשרה אמה — לא יביא זרע לשם, היו שם שש עשרה אמה — נותן לו כדי עבודתו\u0004 כדי המרחק הנחוץ לעיבודו של הכרם מסביב, \u0003וזורע\u0004 לו \u0003את המותר,\u0004 והוא ארבע אמות.","\u0003ואי זו היא מחול הכרם — בין הכרם לגדר. שאם אין שם שתים עשרה אמה — לא יביא זרע לשם,\u0004 ואם \u0003היו שם שתים עשרה אמה — נותן לו כדי עבודתו וזורע את המותר.\u0004 והרי אם לא היתה מחיצה לכרם היה מרחיק ארבע אמות בלבד ונמצאת מחיצה גורמת לאיסור!","\u0003אלא\u0004 משום מה אין אתה מביא ראיה משם — \u0003התם לאו היינו טעמא\u0004 \u0005[שם האם לא זה הטעם]\u0006 ש\u0003כל ארבע אמות לגבי כרם, עבודת הכרם\u0004 ונחוצות לשם עיבודו, ולכך נחשבות כאילו הן חלק ממש מהכרם. וכן ארבע אמות \u0003לגבי\u0004 \u0005[סמוך]\u0006 ל\u0003גדר, כיון\u0004 ש\u0003לא מזדרען\u0004 \u0005[\u0006ניתנות \u0005להזרע]\u0006 מפני שלימות הכותל — \u0003אפקורי מפקר להו\u0004 \u0005[מפקיר אותם].\u0006 \u0003דביני ביני\u0004 \u0005[שבינתיים],\u0006 \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003ארבע\u0004 אמות — \u0003חשיבן\u0004 \u0005[חשובות הן],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא חשיבן\u0004 \u0005[חשובות]\u0006 ובטילות לגבי השאר, ואין זורעים שם. לכן נמצא שהחומרה אינה באה משום שהמחיצה אוסרת, אלא משום שהיא מכבידה ממש על העיבוד החקלאי, אבל אין איסור בא משום המחיצה.","\u0003אמר רב יהודה: שלשה קרפיפות זה בצד זה, ושנים החיצונים מגופפים\u0004 שהם רחבים יותר מן האמצעי ונמצא שיש להם מקצת מחיצות מצידי הפירצה שביניהם. \u0003והאמצעי אינו מגופף,\u0004 שאין לו מחיצות בינו לבין האחרות שהרי הוא צר מהם, \u0003ויחיד בזה ויחיד בזה — נעשה כשיירא ונותנין להן כל צורכן ודאי.\u0004 כלומר שיכולים להשתמש בו אפילו הוא גדול מאד, כפי שהלכה בשיירה שיש בה שלושה אנשים, שכל שטח שהקיפוהו מחיצות — מותר להם להשתמש ולטלטל בכולו.","היה \u0003אמצעי מגופף ושנים החיצונים אינן מגופפין,\u0004 שהם צרים ממנו ופרוצים בכל רחבם אליו, \u0003ויחיד בזה ויחיד בזה — אין נותנין להם אלא בית שש\u0004 סאים כפי שעושים ליחידים בשדה, שאין מתירים להם להשתמש אלא בשטח כדי בית סאתיים בלבד. וטעם ההבדל — שכיון שהקרפף האמצעי גדול, הרי לפי העקרון שהזכרנו, דיורו (כח דירתו) של האמצעי בצדדים ולא להיפך, ואין איפוא שלושה אנשים יחד.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 כאשר היה האמצעי מוקף, והיה \u0003אחד בזה ואחד בזה ושנים באמצעי מהו?\u0004 האם נאמר \u0003אי להכא נפקי — תלתא הוו\u0004 \u0005[אם לכאן\u0006 לצד קרפף זה \u0005יוצאים\u0006 השנים — הרי \u0005שלושה הם\u0006 במקום אחד\u0005],\u0006 \u0003ואי להכא נפקי — תלתא הוו\u0004 \u0005[אם לכאן יוצאים —\u0006 \u0005שלושה הם],\u0006 \u0003וכיון שלגבי שני הצדדים גם יחד הרי הם כששה, ולששה נותנים כל צרכם.\u0004","\u0003או דילמא\u0004 \u0005[שמא]\u0006 נחשב את הדבר כך: \u0003חד להכא נפיק, וחד להכא נפיק\u0004 \u0005[אחד יוצא לכאן, ואחד יוצא לכאן]\u0006 ובכל קרפף מצויים רק שנים, ולשנים אין נותנים אלא כשיעור בית סאתיים לאחד.","\u0003ואם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 אם תקבל את השיטה כי \u0003חד להכא נפיק וחד להכא נפיק\u0004 \u0005[אחד לכאן יוצא ואחד לכאן יוצא],\u0006 אם היו \u0003שנים בזה ושנים בזה ואחד באמצעי מהו?\u0004 האם נאמר: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי, אי להכא נפיק — תלתא הוו, ואי להכא נפיק — תלתא הוו\u0004 \u0005[אם לכאן יוצא —\u0006 \u0005שלושה הם, ואם לכאן יוצא —\u0006 \u0005שלושה הם]\u0006 ובכל צד יש לנו מקום להיתר. \u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר שיש כאן ספק\u0005,\u0006 \u0003אימר להכא נפיק, ואימר להכא נפיק\u0004 \u0005[אמור\u0006 אולי \u0005לכאן יוצא, ואמור שלכאן יוצא],\u0006 וכיון שאין ודאות בדבר נאסור מספק.","בעיות אלו לא נפתרו עקרונית, ואולם \u0003הילכתא\u0004 \u0005[ההלכה]\u0006 המוסכמת היא כי \u0003בעיין לקולא\u0004 \u0005[בעיותינו \u0006אלה\u0005 להקל]\u0006 ולמעשה מקילים ומתירים בכל אלה.","\u0003אמר רב חסדא:\u0004"],["\u0003גידוד חמשה\u0004 כלומר, הבדל גובה של חמישה טפחים שבין שני מקומות, שהאחד צר מחבירו וניכרים מחיצותיו בתוכו, \u0003ו\u0004הוסיפו לו עוד \u0003מחיצה חמשה\u0004 טפחים \u0003— אין מצטרפין\u0004 לעשרה טפחים, להיות נדון כרשות לעצמה \u0003עד שיהא\u0004 גובה עשרה טפחים \u0003או כולו בגידוד או כולו במחיצה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003שתי חצירות זו למעלה מזו ועליונה גבוהה מן התחתונה עשרה טפחים, או שיש בה גידוד חמשה ומחיצה חמשה\u0004 — הרי הן נחשבות מובדלות זו מזו, \u0003ומערבין שנים\u0004 בכל חצר לחוד, \u0003ואין מערבין אחד.\u0004 ואם היה הגובה \u0003פחות מכאן — מערבין אחד, ואין מערבין שנים!\u0004","\u0003אמר רב: מודה רב חסדא ב\u0004חצר ה\u0003תחתונה, הואיל ורואה פני עשרה,\u0004 שהרי מצידה יש מחיצה גמורה של עשרה טפחים. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 הרי לשיטה זו נאמר: \u0003תחתונה\u0004 שמבחינתה יש מחיצה ניכרת — \u0003תערב שנים\u0004 (לבדה) \u0003ולא תערב אחד, עליונה — לא תערב לא אחד ולא שנים,\u0004 שהרי איננה יכולה לערב לעצמה, שכן היא פרוצה לתחתונה. ואף לא לערב יחד, שהתחתונה מובדלת ממנה.","\u0003אמר רבה בר עולא: כגון שהיתה\u0004 חצר \u0003עליונה מגופפת\u0004 במחיצה גמורה \u0003עד עשר אמות,\u0004 ובאותן עשר אמות שהן כעין פתח, מצוי אותו גידוד בן חמישה טפחים שהשלים את גובה המחיצה לעשרה טפחים. ולכן לגבי העליונה נחשב הדבר כמחיצה שיש בה פתח, וכל אחת מערבת לעצמה ומותרת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור את סוף\u0006 אותה ברייתא\u0005]:\u0006 \u0003פחות מכאן — מערבין אחד ואין מערבין שנים,\u0004 והרי לפי ההסבר שאמרנו שיש מחיצה גבוהה עשרה בין החצירות ובאמצעה כעין פתח, במקרה זה \u0003אי בעיא\u0004 \u0005[אם תרצה] —\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 \u0003תערב, אי בעיא\u0004 \u0005[אם תרצה] —\u0006 \u0003תרי\u0004 \u0005[שנים]\u0006 \u0003תערב,\u0004 כדין שתי חצירות שיש פתח ביניהן!","\u0003אמר רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: כגון שנפרצה\u0004 החצר \u0003התחתונה במלואה לעליונה,\u0004 שאותן עשר אמות פתוחות הן כל מלוא רוחבה של החצר התחתונה, ולכן לגבי אותה חצר הריהי פרוצה במלואה לחצר האחרת, ולכן התחתונה אסורה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 החצר ה\u0003תחתונה,\u0004 עירוב \u0003חד\u0004 \u0005[אחד]\u0006 \u0003תערב\u0004 ביחד עם העליונה, \u0003תרי\u0004 \u0005[שנים]\u0006 \u0003לא תערב\u0004 שאינה יכולה לערב לעצמה, \u0003עליונה אי בעיא\u0004 \u0005[אם תרצה] —\u0006 \u0003תרי\u0004 \u0005[שנים]\u0006 \u0003תערב, אי בעיא\u0004 \u0005[אם תרצה] —\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 \u0003תערב.\u0004","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא גם כן]\u0006 הדין. \u0003וכי קתני\u0004 \u0005[וכאשר שנינו]\u0006 \u0003\"פחות מכאן מערבין אחד ואין מערבין שנים\"\u0004 יש להבין שדבר זה לא לשתי החצירות נאמר, אלא על החצר ה\u0003תחתונה\u0004 בלבד נאמר.","\u0003דרש מרימר: גידוד חמשה ומחיצה חמשה\u0004 מעליו \u0005—\u0006 \u0003מצטרפין. אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רבינא לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תני מר מידי\u0004 \u0005[\u0006האם \u0005שנה אדוני משהו]\u0006 \u0003במחיצה\u0004 כגון זו להתיר או לאסור? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא. והלכתא\u0004 \u0005[והלכה]\u0006 נפסקה בדבר: \u0003גידוד חמשה ומחיצה חמשה — מצטרפין.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הושעיא: דיורין הבאין בשבת,\u0004 כלומר שנוספו בשבת במקום. כגון שנהרסו מחיצות שבין שני חצירות ונחשב כאילו נוספו לפתע דיירים חדשים, ואילו היו מבעוד יום היו אוסרים, \u0003מהו שיאסרו\u0004 בתוך יום השבת?","\u0003אמר רב חסדא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, ששנינו: \u0003חצר גדולה שנפרצה לקטנה — הגדולה מותרת, והקטנה אסורה, מפני שהיא כפתחה של גדולה.\u0004 משמע שגם אם נפרצה בשבת עצמה, נאסרת החצר הקטנה. \u0003אמר רבה: אימר\u0004 \u0005[אמור]\u0006 ש\u0003מבעוד יום נפרצה,\u0004 אבל אם אירע דבר זה בשבת אין אוסרים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לא תימא מר \"אימר\"\u0004 \u0005[אל תאמר אדוני \"אמור\"]\u0006 שמשמעו: שמא כך יש לפרש, \u0003אלא\u0004 פירוש זה הוא ש\u0003ודאי מבעוד יום נפרצה. דהא מר\u0004 \u0005[שהרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר בעי מיניה\u0004 \u0005[שאלתי ממנו,\u0006 מאת\u0005]\u0006 \u0003רב הונא ובעי מיניה\u0004 \u0005[ושאלתי ממנו,\u0006 מאת\u0005]\u0006 \u0003רב יהודה: עירב דרך הפתח, ונסתם הפתח\u0004 בשבת. \u0003עירב דרך חלון, ונסתם החלון\u0004 בשבת, \u0003מהו\u0004 לטלטל ביניהם דרך חריצים שנשארו? \u0003ואמר לי: שבת, כיון שהותרה — הותרה.\u0004 ולפי עקרון זה פריצת מחיצה ביום השבת, אף שמוסיפה דיורים — אין לאסור מה שהותר כבר עם כניסת השבת.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר \u0003כותל שבין שתי חצירות\u0004 שלא עירבו ביניהן \u0003שנפל\u0004 בשבת, \u0003רב אמר: אין מטלטלין בו\u0004 בכל השטח כולו \u0003אלא בארבע אמות,\u0004 ששתי החצירות אוסרות זו על זו, משום שלא עירבו יחד. ולא קבל רב את השיטה ששבת כיון שהותרה הותרה.","\u0003ושמואל אמר:\u0004"],["\u0003זה מטלטל עד עיקר\u0004 (יסוד) \u0003מחיצה\u0004 שהיתה, \u0003וזה מטלטל עד עיקר מחיצה,\u0004 שלדעתו שבת כיון שהותרה הותרה.","ומעירים: \u0003והא\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 של \u0003רב — לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש אתמר\u0004 \u0005[נאמר],\u0006 \u0003אלא מכללא אתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמר],\u0006 שמתוך דבריו הסקנו שכך הוא סבור. שכך היה מעשה ש\u0003רב ושמואל הוו יתבי בההוא\u0004 \u0005[היו יושבים באותה,\u0006 באיזו\u0005]\u0006 \u0003חצר, נפל גודא דביני ביני\u0004 \u0005[הכותל שבינתיים,\u0006 שבין שתי החצירות\u0005],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003שמואל: שקולו גלימא, נגידו\u0004 \u0005[קחו גלימה,\u0006 ו\u0005תלו]\u0006 \u0003בה,\u0004 שתהא כמחיצה.","\u0003אהדרינהו\u0004 \u0005[החזיר]\u0006 \u0003רב לאפיה\u0004 \u0005[את פניו],\u0006 להראות שאין דעתו נוחה מדברי שמואל ואסור לדעתו לטלטל את הגלימה באותה חצר. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003שמואל\u0004 בבדיחות הדעת: \u0003אי קפיד\u0004 \u0005[אם מקפיד]\u0006 \u0003אבא\u0004 (רב), \u0003שקולו הימניה וקטרו\u0004 \u0005[קחו\u0006 את \u0005אבנטו\u0006 ו\u0005קשרו]\u0006 \u0003בה\u0004 בגלימה, שתהא כמחיצה שלימה.","ושואלים: \u0003ולשמואל למה לי הא\u0004 \u0005[זאת]\u0006 לשם מה הוצרך לגלימה? והרי הוא עצמו \u0003אמר: זה מטלטל עד עיקר מחיצה וזה מטלטל עד עיקר מחיצה!\u0004","ומשיבים: \u0003שמואל עביד לצניעותא בעלמא\u0004 \u0005[עשה\u0006 זאת \u0005ל\u0006שם \u0005צניעות בלבד]\u0006 שרצה שלא יראו בני החצר האחרת מה נעשה בחצר זו, ולא לצורך היתר טלטול.","ושואלים: \u0003ורב, אי סבירא ליה דאסיר\u0004 \u0005[אם סבור הוא שאסור] —\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו\u0006 בפירוש\u0005]!\u0006 ומשיבים: \u0003אתריה\u0004 \u0005[מקומו]\u0006 של \u0003שמואל הוה\u0004 \u0005[היה],\u0006 ולא רצה רב לחלוק על שמואל באיזור שיפוטו, ששם עליו לקבל את דעת חכם העיר.","ושואלים: \u0003אי הכי, מאי טעמא אהדרינהו לאפיה\u0004 \u0005[אם כך, מה טעם החזיר פניו]\u0006 והרי למעשה הוא צריך לציית לדברי חכם העיר במקומו. ומשיבים: ש\u0003לא נימרו\u0004 \u0005[יאמרו]\u0006 הרואים ש\u0003כשמואל סבירא ליה, והדר ביה משמעתיה\u0004 \u0005[הוא סבור, וחזר בו מהלכתו]\u0006 ומסברתו בנושא זה.","\u0003חצר שנפרצה לרשות הרבים\u0004 פירצה גדולה שאינה יכולה עוד להיחשב כפתח, \u0003המכניס מתוכה לרשות היחיד או מרשות היחיד לתוכה — חייב,\u0004 ששוב אין זו רשות היחיד ובטלה לרשות הרבים, אלו \u0003דברי ר' אליעזר.\u0004","\u0003וחכמים אומרים:\u0004 אם טלטל \u0003מתוכה לרשות הרבים או מרשות הרבים לתוכה — פטור, מפני שהיא ככרמלית,\u0004 שאמנם בטילה מתורת רשות יחיד, אך לא נעשתה על ידי כך כרשות הרבים גמורה.","ושואלים: \u0003ור' אליעזר,\u0004 וכי \u0003משום\u0004 ש\u0003נפרצה\u0004 החצר \u0003לרשות הרבים הויא\u0004 \u0005[נהייתה]\u0006 \u0003לה רשות הרבים?!\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003ר' אליעזר\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לשיטתו]\u0006","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' אליעזר: רבים שבררו דרך לעצמם,\u0004 בתוך שדה או בין השדות, \u0003מה שבררו בררו.\u0004 ואין רשות לסלקם משם אף שהמקום שייך ליחיד. ואם כן אף כאן כיון שנפרצה מחיצת החצר והרבים יכולים להיכנס — הריהו נעשית כרשות הרבים.","ותוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב גידל אמר רב: והוא שאבדה להן דרך באותו שדה.\u0004 כלומר שאין מרשים לרבים לכבוש לעצמם דרך בכל מקום, ושם מדובר רק במקרה שהיתה פעם דרך הרבים בשדה זה ומסיבה כלשהי יצאה מכלל שימוש, שאז יכולים הרבים לשוב לברור להם דרך באותו שדה.","\u0003וכי תימא: הכא נמי\u0004 \u0005[ואם תאמר: כאן גם כן\u0006 מדובר\u0005]\u0006 \u0003כגון שאבדה להם\u0004 לרבים \u0003דרך באותה חצר, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חנינא: עד מקום מחיצה מחלוקת,\u0004 כלומר שחלקו ר' אליעזר וחכמים על כל החצר כולה ולא רק בקטע קטן ממנה על חלקה החיצון שאילו היתה בו דרך לרבים.","ודוחים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003על מקום מחיצה מחלוקת\u0004 שהמחלוקת אינה על גוף החצר אלא רק על המקום שהיתה בו המחיצה, ששם ייתכן שעברה פעם דרך הרבים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר למחלוקת במשנתנו, כאן \u0003בצידי רשות הרבים קמיפלגי\u0004 \u0005[חולקים],\u0006 ש\u0003ר' אליעזר סבר: צידי רשות הרבים — כרשות הרבים דמו\u0004 \u0005[נחשבים]\u0006 שכל הסמוך לרשות הרבים בטל אליה, וכן הוא במקום המחיצה שנפרצה וסמוך לרשות הרבים, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 \u0003צידי רשות הרבים — לאו\u0004 \u0005[לא]\u0006 \u0003כרשות הרבים דמו\u0004 \u0005[נחשבים].\u0006","ושואלים: אם כן, \u0003וליפלוג\u0004 \u0005[ושיחלקו]\u0006 \u0003בצידי רשות הרבים בעלמא\u0004 \u0005[בכלל],\u0006 ומדוע רק במקרה מיוחד זה? ומשיבים: \u0003אי איפליגו\u0004 \u0005[אם היו נחלקים]\u0006 \u0003בצידי רשות הרבים בעלמא\u0004 \u0005[בכלל],\u0006 \u0003הוה אמרינן\u0004 \u0005[היינו אומרים]:\u0006 \u0003כי פליגי רבנן עליה\u0004 \u0005[כאשר נחלקו חכמים עליו]\u0006 על \u0003ר' אליעזר — הני מילי היכא דאיכא חיפופי\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שיש יתדות\u0006 בצידי הבתים\u0005]\u0006 המפריעות להשתמש בצידי רשות הרבים, \u0003אבל היכא דליכא חיפופי\u0004 \u0005[במקום שאין יתדות\u0006 כאלה\u0005]\u0006 \u0003אימא מודו ליה\u0004 \u0005[אמור\u0006 ש\u0005מודים לו],\u0006 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שנחלקו בכל מקרה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מתוכה\" קאמר\u0004 \u0005[הוא אומר],\u0006 שבמשנה שנינו \"הכניס מתוכה לרשות היחיד\", ומשמעות לשון זו שהכוונה לא רק סמוך לרשות הרבים אלא אפילו בכל חלקי החצר, שכולה נחשבת כרשות הרבים!","ומשיבים: \u0003איידי דאמור רבנן\u0004 \u0005[כיון שאמרו חכמים]\u0006 \u0003\"מתוכה\", אמר איהו נמי\u0004 \u0005[אמר הוא גם כן]\u0006 \u0003\"מתוכה\",\u0004 אבל אין לדייק בדבריו, וכוונתו רק לחלק הסמוך לרשות הרבים.","ומקשים: אם כן, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד נבין את דבריהם? הרי \u0003אמר ר' אליעזר צידי רשות הרבים\u0004 דינם כרשות הרבים, \u0003ומהדרו ליה אינהו\u0004 \u0005[ומשיבים הם לו]\u0006 בענין \u0003\"מתוכה\"\u0004 של החצר, והרי אין תשובתם ממין הטענה כלל!","ומשיבים: \u0003הכי קאמרי ליה רבנן\u0004 \u0005[כך אומרים לו חכמים]\u0006 \u0003לר' אליעזר,\u0004 וזו כוונתם: \u0003מי לא קא מודית לן\u0004 \u0005[האם אינך מודה לנו]\u0006 \u0003היכא\u0004 \u0005[היכן,\u0006 אם\u0005]\u0006 \u0003טלטל מתוכה לרשות הרבים, ומרשות הרבים לתוכה\u0004 שהוא \u0003פטור מפני שהיא כרמלית,\u0004 אם כן \u0003צידי\u0004 רשות הרבים \u0003נמי לא שנא\u0004 \u0005[גם כן אינו שונה],\u0006 ומסתבר שדינם ככרמלית.","\u0003ור' אליעזר\u0004 מה משיב הוא על טענה זו? \u0003התם\u0004 \u0005[שם]\u0006 בצידי הדרך \u0003לא קא דרסי לה\u0004 \u0005[אין דורסים אותה]\u0006 \u0003רבים, הכא\u0004 \u0005[כאן]\u0006 \u0003קא דרסי לה\u0004 \u0005[דורסים אותה]\u0006 \u0003רבים,\u0004 ולכן דינה כרשות הרבים לכל דבר.","\u0003חצר שנפרצה\u0004 בשבת \u0003לרשות הרבים משתי רוחותיה, וכן בית שנפרץ\u0004 בשבת \u0003משתי רוחותיו, וכן מבוי שנטלו קורותיו או לחייו בשבת — מותרים באותו שבת, ואסורים לעתיד לבא\u0004 (לשבת אחרת), אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' יוסי אומר:\u0004 אי אפשר לומר כן, ש\u0003אם מותרין לאותו שבת,\u0004 יהיו \u0003מותרין לעתיד לבא, ואם אסורין לעתיד לבא — אסורין\u0004 אף \u0003לאותו שבת.\u0004","שואלים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו],\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיתה הפירצה רחבה עד \u0003עשר\u0004 אמות, אם כן \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 כשהיתה הפירצה \u0003מרוח אחת — דאמר פיתחא\u0004 \u0005[שאומר\u0006 אתה \u0005פתח]\u0006 \u0003הוא,\u0004 ולא פירצה, ועדיין מותר בטלטול, אף אם נפרצה \u0003משתי רוחות\u0004 האחת כנגד השניה \u0003נמי פיתחא\u0004 \u0005[גם כן פתח]\u0006 \u0003הוא\u0004 ויהיו לחצר זו פתחים משני צידיה! \u0003אלא\u0004 ודאי יש לפרש נפרצה \u0003ביתר מעשר, אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו מרוח אחת נמי\u0004 \u0005[גם כן]\u0006 הפירצה מבטלת את כל המחיצות!","\u0003אמר רב: לעולם\u0004 תפרש שהיתה הפירצה \u0003בעשר\u0004 אמות או פחות מכן,"],["\u0003וכגון שנפרצה\u0004 החצר \u0003בקרן זוית,\u0004 וממילא היתה זו פירצה בשתי רוחות. ואף שהיא בעשר אמות אין לומר שפירצה זו פתח היא, \u0003דפיתחא\u0004 \u0005[שפתח]\u0006 \u0003בקרן זוית לא עבדי אינשי\u0004 \u0005[עושים אנשים],\u0006 וניכר לכול שהיא פירצה, והריהי מבטלת את דין המחיצה.","שנינו במשנה: \u0003\"וכן בית שנפרץ משתי רוחותיו\".\u0004 ותוהים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 אם נפרץ הבית רק \u0003מרוח אחת דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003פי תקרה\u0004 (קצה התקרה) נחשב כ\u0003יורד וסותם,\u0004 וכאילו היתה שם מחיצה. ואם כן, אם נפרץ \u0003משתי רוחות נמי לימא\u0004 \u0005[נאמר גם כן]:\u0006 \u0003פי תקרה יורד וסותם!\u0004","ומשיבים, \u0003אמרי דבי\u0004 \u0005[אמרו בני בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כגון שנפרץ\u0004 הבית \u0003בקרן זוית. ו\u0004עוד, כש\u0003קירויו\u0004 של הבית \u0003באלכסון, דליכא\u0004 \u0005[ש\u0006אז \u0005אין\u0006 לומר\u0005]\u0006 ש\u0003פי תקרה יורד וסותם,\u0004 שכן קירוי אלכסוני אינו נראה כיוצר מחיצה. עד כאן שיטת רב בפירוש המשנה.","\u0003ושמואל אמר\u0004 שמה ששנינו \"נפרץ\" הכונה היא: \u0003אפילו ביתר מעשר.\u0004 ותוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדוע דוקא בנפרץ משתי רוחותיו? \u0003מרוח אחת נמי\u0004 \u0005[גם כן]\u0006 יהא אסור!","ומשיבים: \u0003משום בית.\u0004 כלומר, לענין חצר גם אם היתה פירצתה מרוח אחת הוא הדין, אבל השתמשה המשנה בסגנון זה משום שרצתה ללמדנו גם דין הבית, ובו הפירצה היא משתי רוחות דוקא, שהרי ברוח אחת אומרים פי תקרה יורד וסותם.","ושואלים: \u0003ובית גופיה תקשי\u0004 \u0005[עצמו יהיה קשה]\u0006 להסבר זה; \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003מרוח אחת, דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003פי תקרה יורד וסותם,\u0004 ואין הבית נחשב כפרוץ, \u0003משתי רוחות נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 \u0003פי תקרה יורד וסותם!\u0004","\u0003ותו\u0004 \u0005[ועוד]\u0006 אפשר להקשות: \u0003מי אית ליה\u0004 \u0005[האם יש לו]\u0006 \u0003לשמואל\u0004 לשיטתו \u0003פי תקרה יורד וסותם? והא אתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו בבעיה של \u0003אכסדרה בבקעה,\u0004 ש\u0003רב אמר: מותר לטלטל בכולה\u0004 שלדעתו פי תקרה של אכסדרה יורד וסותם, \u0003ושמואל אמר: אין מטלטלין בה אלא בארבע אמות,\u0004 הרי שלדבריו אין אומרים פי תקרה יורד וסותם!","ומשיבים: \u0003הא\u0004 \u0005[\u0006קושיה אחרונה \u0005זו]\u0006 \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 כשאינו מקבל את השיטה, שפי תקרה יורד וסותם כוונתו היא \u0003בארבע\u0004 רוחות, שאין אומרים בכולן פי תקרה יורד וסותם, \u0003אבל בשלש\u0004 רוחות בלבד ומחיצה רביעית כתיקונה, הרי \u0003אית ליה\u0004 \u0005[יש לו]\u0006 פי תקרה מועיל לרוחות אחרות.","ומעירים: \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 שהרי אף אם פתרנו את הסתירה בעצם שיטת שמואל, את הבעיה בדבר שתי רוחות שאין אומרים בהם פי תקרה יורד וסותם לא תירצנו!","ומשיבים: \u0003כדאמרי בי\u0004 \u0005[כמו שאמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כגון שנפרץ בקרן זוית וקירויו באלכסון, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נפרש על פי שיטת שמואל במצב דומה, \u0003כגון שנפרץ בקרן זוית וקירויו בארבע\u0004 שהקירוי אינו מעל לפירצה אלא במרחק מסויים מן הכותל, לפחות ארבעה טפחים בצורה לא ישרה, אלא באופן שנוצרים בקרן זווית זו עצמה ארבע זוויות חדשות הסמוכות זו לזו, שאז צריך לומר \"פי תקרה יורד וסותם\" מארבעה צדדים, ובכגון זה לא התיר שמואל.","ומסבירים הטעם ש\u0003שמואל לא אמר כרב\u0004 בפירוש המשנה, כי \u0003אלכסון לא קתני\u0004 \u0005[שנינו\u0006 כלל\u0005]\u0006 והרי זהו עיקר בפירוש רב. \u0003ורב לא אמר כשמואל,\u0004 ש\u0003אם כן\u0004 גם אם נפרץ הקירוי מכמה צדדים באופן כזה \u0003הויא ליה\u0004 \u0005[הרי הוא\u0006 נעשה\u0005]\u0006 כ\u0003אכסדרה, ורב לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר אכסדרה מותר לטלטל בכולה.\u0004","כיון שדברי רב ושמואל שאמרנו קשורים במחלוקתם לענין אכסדרה, מביאים כאן אותה מחלוקת בשלימותה. \u0003דאיתמר\u0004 \u0005[שנאמר],\u0006 \u0003אכסדרה\u0004 שהיתה מצויה \u0003בבקעה. רב אמר: מותר לטלטל\u0004 באכסדרה \u0003כולה,\u0004 שהיא נחשבת כסגורה. \u0003ושמואל אמר: אין מטלטלין בה אלא בארבע אמות,\u0004 שאין לאכסדרה מחיצות גמורות והיא בטלה לבקעה ונעשית אף היא כרמלית כמותה.","ומסבירים, \u0003רב אמר: מותר לטלטל בכולה,\u0004 שלדעתו \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003פי תקרה\u0004 של אכסדרה \u0003יורד\u0004 למטה \u0003וסותם,\u0004 ויוצר כעין מחיצה. וכיון שיש קירוי לאכסדרה, הריהי ממילא כסתומה בדפנות מכל צד. \u0003ושמואל אמר: אין מטלטלין בה אלא בארבע אמות,\u0004 כי \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003פי תקרה יורד וסותם.\u0004","ומפרטים: אם היה המקום הפתוח באכסדרה \u0003בעשר\u0004 אמות בלבד — \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חלוקים]\u0006 שדינה כסגורה, שהרי אף פירצה בלתי מקורה של עשר אמות או פחות דינה כפתח ומותרת כולה בטלטול. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה — \u0003ביתר מעשר.\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 לא כך, וסבורים כי \u0003ביתר\u0004 מעשר — \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חלוקים]\u0006 שפירצה היא, ואין פי תקרה סותמה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003בעשר\u0004 אמות או פחות.","\u0003והא\u0004 \u0005[וזו]\u0006 ש\u0003אמר רב יהודה:\u0004"],["\u0003קורה\u0004 המונחת על גבי יתידות שרוחבה \u0003ארבעה\u0004 טפחים \u0003מתיר בחורבה\u0004 הפרוצה לרשות הרבים, שפי הקורה נחשב כיורד עד למטה וסותם את הפירצה. \u0003ורב נחמן אמר רבה בר אבוה: קורה ארבעה\u0004 טפחים \u0003מתיר במים\u0004 כמחיצה. \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי הוא]?\u0006","ומסבירים: \u0003להך לישנא\u0004 \u0005[ללשון,\u0006 נוסחה\u0005, זו]\u0006 \u0003שאמרת בעשר\u0004 אמות \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 רב ושמואל, אם כך מדובר כאן \u0003ב\u0004קורה שאורכה \u0003עשר\u0004 אמות, \u0003ו\u0004הלכה זו כ\u0003דברי הכל. להך לישנא\u0004 \u0005[ללשון,\u0006 נוסחה\u0005, זו]\u0006 \u0003שאמרת בעשר\u0004 אמות \u0003פליגי\u0004 \u0005[נחלקו],\u0006 תהא זו כשיטת \u0003רב\u0004 בלבד.","מציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003אביי ורבא בפלוגתא\u0004 \u0005[במחלוקתם]\u0006 של \u0003רב ושמואל קמיפלגי\u0004 \u0005[נחלקו],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שדנו בבעיה של מי ש\u0003סיכך על גבי אכסדרה שיש לה פצימין,\u0004 כלומר עמודים היוצרים כעין תחילות מחיצות, ואינם רחבים שלושה טפחים — \u0003כשירה,\u0004 אבל אם סיכך על אכסדרה ש\u0003אין לה פצימין, אביי אמר: כשירה, ורבא אמר: פסולה.\u0004 ומפרטים: \u0003אביי אמר כשירה,\u0004 שכן \u0003אמר\u0004 (סבר) כי \u0003פי תקרה יורד וסותם,\u0004 וכיון שיש לאכסדרה קירוי — הריהו כמחיצה. \u0003ורבא אמר פסולה,\u0004 כי \u0003לא אמר\u0004 (סבר) \u0003פי תקרה יורד וסותם.\u0004 האם \u0003לימא\u0004 \u0005[נאמר]\u0006 כי \u0003אביי\u0004 סבר \u0003כרב, ורבא כשמואל?\u0004","","ומשיבים: \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003שמואל כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חלוקים],\u0006 וגם אביי מודה שלשיטתו אין סוכה כזו כשירה, שפי תקרה זו לא נעשה לשם הסוכה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003הרי זה אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003רב, אביי — כרב\u0004 כמשמעות דבריו. \u0003ורבא\u0004 טוען — \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רב התם\u0004 \u0005[שם]\u0006 שפי תקרת אכסדרה יורד וסותם, \u0003אלא דהני\u0004 \u0005[שאותן]\u0006 \u0003מחיצות\u0004 הנוצרות מחמת הקירוי, לצורך \u0003אכסדרה עבידי\u0004 \u0005[עשויות],\u0006 והריהן כסותמות את האכסדרה. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003דהני\u0004 \u0005[שאלה]\u0006 \u0003מחיצות לאו\u0004 \u0005[לא]\u0006 \u0003ל\u0004צורך מצות \u0003סוכה עבידי\u0004 \u0005[נעשו],\u0006 יתכן שיסכים אף רב שאינן חשובות כדי לסמוך עליהן לצורך מצוה זו. במשנתנו מובא כי \u0003ר' יוסי אומר: אם מותרין\u0004 בשבת זו כשנפלו המחיצות, מותרים בכל שבת. ואם אסורים, אסורים אף בשבת ראשונה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 האם להלכה התכוון \u0003ר' יוסי לאסור, או להתיר\u0004 בכל מקרה?","","\u0003אמר רב ששת: לאסור. וכן אמר ר' יוחנן: לאסור. תניא נמי הכי\u0004 \u0005[שנויה גם כן כך\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: כשם שאסורין לעתיד לבא, כך אסורין לאותו שבת.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדין, \u0003רב חייא בר יוסף אמר: הלכה כר' יוסי, ושמואל אמר: הלכה כר' יהודה.\u0004","ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?!\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003אמר ר' יהודה: במה דברים אמורים,\u0004 שצריכים לשאול לדעתו של מי שמערבים עבורו, \u0003בעירובי תחומין\u0004 שיש בהם גם צד חומרה וחוב למי שמערבים עבורו, שהרי מתוך שהותר לו הילוך לצד אחד, נאסר עליו ההילוך לצד האחר. \u0003אבל בעירובי חצירות — מערבין בין לדעת בין שלא לדעת.\u0004 וטעמו של דבר, \u0003לפי שזכין לאדם שלא בפניו,\u0004 ולכך אין צריך להודיעו, \u0003ואין חבין שלא בפניו\u0004 אלא מדעתו ומרצונו.","\u0003ואמר רב יהודה אמר שמואל: הלכה כר' יהודה\u0004 בענין זה. \u0003ולא עוד אלא, כל מקום ששנה ר' יהודה בעירובין — הלכה כמותו.\u0004 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנא בגדתאה\u0004 \u0005[מבגדד]\u0006 \u0003לרב יהודה:\u0004 האם \u0003אמר שמואל\u0004 שהלכה כר' יהודה \u0003אפילו במבוי שניטל קורתו או לחייו\u0004 בתוך השבת? \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעירובין אמרתי לך, ולא במחיצות.\u0004 ואם כן כיצד פסק שמואל הלכה כר' יהודה לאחר שאמר במפורש שאין הלכה כמותו במחיצות שנפלו?","","\u0003אמר רב ענן: לדידי מיפרשא לי מניה דשמואל\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו, משמואל\u0006 עצמו\u0005]\u0006 \u0003כאן — שנפרצה\u0004 החצר \u0003לכרמלית,\u0004 מותרת לפי שאין בכך חשש לאיסור מן התורה, \u0003כאן — שנפרצה לרשות הרבים,\u0004 יש חשש איסור תורה, ואסורה.","\u0003הבונה עלייה על גבי שני בתים\u0004 שמשני צידי רשות הרבים, ורשות הרבים עוברת תחתיה. \u0003וכן גשרים המפולשים\u0004 שרשות הרבים עוברת מתחתם \u0003— מטלטלין תחתיהן בשבת,\u0004 אלו \u0003דברי ר' יהודה.\u0004 שלדעתו אין צורך ביותר מכן כדי שיחשב המקום שבינתים לרשות היחיד. \u0003וחכמים אוסרין.\u0004 \u0003ועוד אמר ר' יהודה: מערבין\u0004 אף \u0003למבוי המפולש\u0004 משני צידיו בלא תיקון נוסף. \u0003וחכמים אוסרין.\u0004","","\u0003אמר רבה: לא תימא היינו טעמא\u0004 \u0005[תאמר\u0006 ש\u0005זהו הטעם]\u0006 של \u0003ר' יהודה משום דקא סבר\u0004 \u0005[שהוא סבור]\u0006 ש\u0003שתי מחיצות\u0004 הן \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ומקום שיש בו שתי מחיצות בלבד הריהו לפי דין תורה (כהלכה למשה מסיני) כמקום סגור, ומשום כך השטח שבין שני הבתים החוסמים את הרחוב משני צדדיו דינו כרשות היחיד. \u0003אלא משום דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003פי תקרה יורד וסותם,\u0004 שהרי שולי העליה או הגשר נחשבים כסותמים את המקום שבאמצע.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 מן הנאמר בברייתא: \u0003יתר על כן אמר ר' יהודה: מי שיש לו שני בתים משני צידי רשות הרבים — עושה לחי מכאן ולחי מכאן, או קורה מכאן וקורה מכאן, ונושא ונותן באמצע.\u0004 ושם ברור שאין טעמו משום פי תקרה יורד וסותם, שאין מדובר שם בקורה כלל, אלא ודאי משום שסבר שבשתי מחיצות די לפי דין התורה. \u0003אמרו לו:\u0004 הרי \u0003אין מערבין רשות הרבים בכך?\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 אכן \u0003מההיא\u0004 \u0005[מאותה\u0006 ברייתא\u0005] —\u0006 \u0003אין\u0004 \u0005[כן]\u0006 אפשר להסיק זאת\u0005,\u0006 \u0003מהא\u0004 \u0005[מזו] —\u0006 \u0003ליכא למשמע מינה\u0004 \u0005[אין אפשרות לשמוע ממנה]\u0006 כי אפשר לפרש את דברי ר' יהודה גם מתוך טעם אחר.","","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדויקת]\u0006 שטעמו של ר' יהודה הוא משום ששתי מחיצות מועילות מן התורה. \u0003מדקתני\u0004 \u0005[ממה ששנינו]:\u0006 \u0003ועוד אמר ר' יהודה: מערבין במבוי המפולש, וחכמים אוסרין.\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003משום דקא סבר\u0004 \u0005[שהוא סבור]\u0006 \u0003פי תקרה יורד וסותם — היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 \u0003\"ועוד\",\u0004 להתיר גם בזו, וללמדנו שאותה הלכה עצמה חלה לא רק על מקום שיש לו קירוי אלא גם במבוי המפולש שאינו מקורה, אף שלא שייך בו טעם זה.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהתיר ר' יהודה \u0003משום דקא סבר\u0004 \u0005[שהוא סבור]\u0006 \u0003שתי מחיצות דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 ה\u0003\"ועוד\"\u0004 שבכך. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[נלמד מכאן]\u0006 שכך הוא. \u0003המוצא תפלין\u0004 בשבת מחוץ לעיר במקום שיש לחשוש שיאבדו ויתקלקלו — \u0003מכניסן\u0004 את התפילין \u0003זוג זוג\u0004 כדרך הנחתן למצוה וכך מכניסן אל ביתו. \u0003רבן גמליאל אומר:\u0004 מכניסן \u0003שנים שנים. במה דברים אמורים\u0004 שמותר לטלטל ולהכניס את התפילין — \u0003ב\u0004תפילין \u0003ישנות,\u0004 שברור שהשתמשו בהן כבר והן מיוחדות למצותן. \u0003אבל בחדשות,\u0004 שאין ידוע אם תפילין הן או שמא קמיע סתם הוא שצורתו כתפילין — \u0003פטור.\u0004","","","\u0003מצאן צבתים\u0004 (חבילות קשורות) \u0003או כריכות\u0004 (ערימות כרוכות) שאינו יכול להכניסן זוג זוג — \u0003מחשיך עליהן\u0004 כלומר, ישב שם וישמרם עד סוף יום השבת \u0003ומביאן\u0004 אז לביתו."],["\u0003ובסכנה\u0004 שמסוכן להמתין מחוץ לעיר — \u0003מכסן\u0004 את התפילין \u0003והולך לו.\u0004","\u0003ר' שמעון אומר\u0004 דרך אחרת להעברת התפילין: \u0003נותנן לחברו\u0004 העומד במרחק של פחות מארבע אמות ממנו, \u0003וחבירו לחבירו, עד שמגיע לחצר החיצונה\u0004 של העיר. וכיון שאין איסור מן התורה בטלטול פחות מארבע אמות ברשות הרבים התירו חכמים מפני קדושת התפילין.","\u0003וכן בנו\u0004 אם נולד לו בשדה, שאסור לו לקחתו בשבת על ידיו, שהוא כמטלטל משא ברשות הרבים — \u0003נותנו לחבירו, וחבירו לחבירו, אפילו\u0004 היו שם \u0003מאה\u0004 בני אדם. \u0003ר' יהודה אומר:\u0004 אף \u0003נותן אדם חבית לחבירו, וחבירו לחבירו,\u0004 וכך יכול לטלטלה \u0003אפילו\u0004 מ\u0003חוץ לתחום,\u0004 בתנאי שלא יעבירה אדם אחד יותר מארבע אמות. \u0003אמרו לו: לא תהלך זו\u0004 החבית \u0003יותר מרגלי בעליה,\u0004 שאין לטלטל את החבית הרחק יותר משמותר לבעליה ללכת.","במשנה שנינו שלוקחן זוג זוג, משמע מכאן כי \u0003זוג אחד — אין\u0004 \u0005[כן]\u0006 מותר, \u0003טפי\u0004 \u0005[יותר]\u0006 — \u0003לא.\u0004 ושואלים: \u0003לימא תנן סתמא\u0004 \u0005[האם לומר\u0006 ש\u0005שנינו\u0006 משנה \u0005סתם]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' מאיר?\u0004 למרות הכלל שכרגיל סתם משנה ר' מאיר היא.","\u0003דאי\u0004 \u0005[שאם]\u0006 תאמר \u0003כר' מאיר\u0004 היא, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' מאיר: בשעת השריפה מותר לטלטל מביתו בשבת בדרך לבישה, ו\u0003לובש כל מה שיכול ללבוש, ועוטף כל מה שיכול לעטוף. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ולשם\u0004 לחצר הסמוכה למקום השריפה \u0003מוציא כל כלי תשמישו, ולובש כל מה שיכול ללבוש, ועוטף כל מה שיכול לעטוף.\u0004","דרך אגב תוהים: \u0003וההיא סתמא\u0004 \u0005[ואותה\u0006 משנה \u0005סתם]\u0006 בענין שבת \u0003ממאי\u0004 \u0005[מנין]\u0006 יודעים אנו שכשיטת \u0003ר' מאיר היא? דקתני עלה\u0004 \u0005[ש\u0006כן \u0005שנינו עליה]:\u0006 \u0003לובש ומוציא, ופושט ולובש ומוציא ופושט, אפילו כל היום כולו, דברי ר' מאיר.\u0004","כדי לתרץ את השאלה \u0003אמר רבא: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' מאיר, התם\u0004 \u0005[שם]\u0006 אם לובש את הבגדים כ\u0003דרך מלבושו — כיום חול שוויה רבנן\u0004 \u0005[עשו אותו חכמים],\u0006 שהתירו ללבוש בשבת ולהוציא את המלבושים כדרך שלבוש בחול. \u0003והכא\u0004 \u0005[ו\u0006אף \u0005כאן]\u0006 כשמניחם \u0003דרך מלבושו\u0004 כיום \u0003חול שוויה רבנן\u0004 \u0005[עשו אותו חכמים].\u0006","ולכן, \u0003התם\u0004 \u0005[שם]\u0006 שביום \u0003חול כמה\u0004 בגדים \u0003דבעי לביש\u0004 \u0005[שרוצה\u0006 הוא \u0005לובש],\u0006 \u0003לענין הצלה נמי שרו ליה רבנן\u0004 \u0005[גם כן התירו לו חכמים]\u0006 ללבוש כמה בגדים שירצה. \u0003הכא\u0004 \u0005[כאן]\u0006 בתפילין שביום \u0003חול נמי\u0004 \u0005[גם כן],\u0006 \u0003זוג אחד — אין\u0004 \u0005[כן]\u0006 הוא מניח, \u0003טפי\u0004 \u0005[יותר] —\u0006 \u0003לא. לענין הצלה נמי\u0004 \u0005[גם כן]\u0006 \u0003זוג אחד\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 התירו לו, \u0003טפי\u0004 \u0005[יותר]\u0006 — \u0003לא.\u0004","שנינו במשנה ש\u0003רבן גמליאל אומר: שנים שנים.\u0004 ותוהים: \u0003מאי קסבר\u0004 \u0005[מה הוא סבור],\u0006 ומה טעמו בהלכה זו? \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 כי \u0003שבת זמן\u0004 הנחת \u0003תפילין הוא,\u0004 ומותר (או חובה) להניח תפילין בשבת, אם כן \u0003זוג אחד — אין\u0004 \u0005[כן],\u0006 \u0003טפי\u0004 \u0005[יותר]\u0006 — \u0003לא,\u0004 שאין להניח יותר מזוג אחד, והמוסיף עליהן — עובר משום \"בל תוסיף\".","\u0003ואי קסבר\u0004 \u0005[ואם הוא סבור]\u0006 \u0003שבת לאו\u0004 \u0005[לא]\u0006 \u0003זמן\u0004 הנחת \u0003תפילין הוא, ומשום הצלה דרך מלבוש שרו ליה רבנן\u0004 \u0005[התירו לו חכמים],\u0006 אם כן, \u0003אפילו טפי\u0004 \u0005[יותר]\u0006 מכרגיל \u0003נמי\u0004 \u0005[גם כן]\u0006 ילבש, שיניח כל הזוגות שיכול ללבוש, ולאו דוקא שנים!","ומשיבים: \u0003לעולם קסבר\u0004 \u0005[\u0006תפרש \u0005שסבור הוא]\u0006 \u0003שבת לאו\u0004 \u0005[לא]\u0006 \u0003זמן\u0004 הנחת \u0003תפילין הוא, וכי שרו\u0004 \u0005[וכאשר התירו]\u0006 חכמים \u0003לענין הצלה\u0004 — הרי זה \u0003דרך מלבוש במקום תפילין,\u0004 אבל אין לקשור תפילין במקום שאינו מקום הנחתם, שאין זו דרך לבישתן אלא משא בלבד.","\u0003ומקשים: אי הכי\u0004 \u0005[אם כן]\u0006 \u0003זוג אחד נמי\u0004 \u0005[גם כן]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 מותר, \u0003טפי\u0004 \u0005[יותר]\u0006 — \u0003לא,\u0004 שהרי זוג שני מניח כבר שלא במקומו! \u0003אמר רב שמואל בר רב יצחק: מקום יש בראש להניח בו שתי תפילין.\u0004 ומשום כך, הנותן שני בתי תפילין בראשו — הריהו מניחם כדרך לבישתם.","ושואלים: \u0003הניחא\u0004 \u0005[נניח]\u0006 בשל \u0003ראש\u0004 שיש בו מקום לשני בתים, ואולם תפילין של \u0003יד מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 ולהסביר כיצד מניח שני בתים?","ומשיבים שאף כשמניח שני בתים על ידיו הרי זו כדרך לבישתן, כפי שאמר \u0003 רב הונא,\u0004 ש\u0003אמר רב הונא: פעמים שאדם בא מן השדה וחבילתו על ראשו,\u0004 וכדי שלא תמעך את התפילין, הרי הוא \u0003מסלקן מראשו וקושרן בזרועו.\u0004 משמע שיש בזרוע מקום גם עבור בית תפילין נוסף!","ודוחים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר רב הונא\u0004 שרשאי להסיר את התפילין מראשו ולקושרן לפי שעה על זרועו, רק כדי \u0003שלא ינהג בהן דרך בזיון,\u0004 שלא יהיו מונחים תחת החבילה. ואולם שהמקום \u0003ראוי\u0004 לתפילין \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר,\u0004 וכי אפשר להוכיח מכאן שראוי לכתחילה להניח ביד עוד בית?","\u0003אלא\u0004 יש לומר כי כשם ש\u0003אמר רב שמואל בר רב יצחק: מקום יש בראש שראוי להניח בו שתי\u0004 בתי \u0003תפילין. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מקום יש ביד שראוי להניח בו שתי\u0004 בתי \u0003תפילין.\u0004","מעירים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה\u0004 מה שנאמר \"וקשרתם לאות על ידך והיו לטטפות בין עיניך\" (דברים ו, ח) \u0003\"על ידך\" — זו קיבורת\u0004 מקום השריר שביד, \u0003\"בין עיניך\" — זו קדקד.\u0004 ושאלו: \u0003היכא\u0004 \u0005[היכן]\u0006 הוא המקום המדויק בקדקד? \u0003אמרי דבי [אמרו מבית\u0004 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 מדובר ב\u0003מקום שמוחו של תינוק רופס\u0004 (רך) בימיו הראשונים, הוא המקום שיש להניח עליו תפילין.","ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 \u0003בדרב שמואל בר רב יצחק קמיפלגי\u0004 \u0005[נחלקו]\u0006 התנאים במשנה, ש\u0003תנא קמא לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003רב שמואל בר רב יצחק,\u0004 שיש מקום בראש לשני זוגות תפילין, \u0003ורבן גמליאל אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 שיטת \u0003רב שמואל בר רב יצחק,\u0004 ולכן מתיר לקחת שני זוגות?","ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[הכול יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003רב שמואל בר רב יצחק, והכא\u0004 \u0005[וכאן]\u0006 המחלוקת היא \u0003ב\u0004שאלה אם \u0003שבת זמן תפילין\u0004 הוא; ש\u0003תנא קמא סבר\u0004 \u0005[סבור]:\u0006 \u0003שבת זמן תפילין הוא,\u0004 ויום השבת יום ראוי להנחת תפילין. ולכן אף שהותר בהנחת זוג אחד, אסור להוסיף על המצוה ולהניח זוג אחר. ואם הניח, אינו אלא כמשאוי ואסור.","\u0003ורבן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003שבת לאו\u0004 \u0005[לא]\u0006 \u0003זמן תפילין הוא,\u0004 ויכול ללבוש יותר מזוג אחד, שהרי אין היום ראוי כלל להנחת תפילין, ואין בכך משום תוספת על המצוה בתורה ולענין הצלה החשיבוהו כתכשיט וביותר משני זוגות שוב אינו נחשב כתכשיט.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאפשר להסביר את טעמי המחלוקת כך: \u0003דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל]\u0006 \u0003שבת זמן תפילין הוא, והכא\u0004 \u0005[וכאן]\u0006 בשאלה אם \u0003מצות צריכות כוונה קמיפלגי\u0004 \u0005[נחלקו].\u0006 כיצד: \u0003תנא קמא סבר\u0004 כי \u0003לצאת\u0004 ידי חובת המצוה \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 ואם אינו מתכוון אין כאן מצווה כלל ואינו אלא מטלטל משא סתם. ואם מתכוון לצאת ידי חובה, הרי משום \"בל תוסיף\" אסור לו להניח יותר מזוג אחד, ואם הניח אינו אלא כמשא.","\u0003ורבן גמליאל סבר: לא בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 כדי לצאת ידי חובה, ואם מניח שני זוגות תפילין — יצא ידי חובתו באחד מהם, אבל אינו עובר משום \"בל תוסיף\", כי לשם כך יש צורך שיתכוון במפורש לקיים מצוה נוספת על ידי תוספת השני."],["\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל]\u0006 כדי \u0003לצאת\u0004 ידי חובת מצוה \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה, והכא\u0004 \u0005[וכאן]\u0006 בשאלה בענין \u0003לעבור משום \"בל תוסיף\" קמיפלגי\u0004 \u0005[נחלקו],\u0006 \u0003דתנא קמא\u0004 \u0005[שהתנא הראשון]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לעבור משום \"בל תסיף\" לא בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה,\u0004 ולכן אם יניח זוג תפילין נוסף, אף אם לא יתכוון בהנחתם לשם מצוה, הריהו עובר ב\"בל תוסיף\". \u0003ורבן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003לעבור משום \"בל תסיף\" בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 של עשיית מצוה. וכיון שכאן אינו מתכוון אלא לטלטול התפילין בלבד, יכול להניח עוד זוג.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003אי דסבירא לן\u0004 \u0005[אם שסבורים אנו]\u0006 ש\u0003שבת זמן תפילין\u0004 הוא — \u0003דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל]\u0006 \u0003לא לעבור\u0004 על \"בל תוסיף\" \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה ולא לצאת\u0004 ידי חובת המצוה \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה,\u0004 וכיון שעשה מעשה אין כוונתו מעלה או מורידה.","\u0003והכא\u0004 \u0005[וכאן]\u0006 בענין \u0003\"לעבור שלא בזמנו\"\u0004 על \"בל תוסיף\" כשעושים מצוה שלא בזמנה \u0003קמיפלגי\u0004 \u0005[נחלקו],\u0006 וכך יש להבין: \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 שאם עושים מעשה מצוה שלא בזמנה \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 שיתכוון אז לעשיית המצוה, אלא כיון שעשה הריהו עובר על \"בל תוסיף\", לכן אסור לו להניח יותר מזוג אחד. \u0003ורבן גמליאל סבר\u0004 \u0005[סבור]:\u0006 ש\u0003לעבור שלא בזמנו בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 למצוה, ואם אינו מתכוון, אינו עובר, ולכן יכול להניח זוג נוסף.","על הסבר זה מקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 לדעת \u0003ר' מאיר זוג אחד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יניח, שהרי בעצם הנחתו עובר הוא משום \"בל תוסיף\", שמקיים מצות תפילין בזמן שאינו מצווה על כך.","\u0003ועוד\u0004 שלפי זה \u0003הישן בשמיני\u0004 עצרת \u0003בסוכה ילקה\u0004 משום \"בל תוסיף\", שמוסיף על המצוה \"בסוכות תשבו שבעת ימים\". והרי תיקנו חכמים שבגלות יקיימו שמונה ימי חג ושני ימים טובים של גלויות, ואם כן הישן בסוכה בליל שמיני בגולה עובר על דברי תורה! \u0003אלא מחוורתא כדשנינן מעיקרא\u0004 \u0005[מחוור,\u0006 ברור\u0005, כמו שתרצנו בתחילה]\u0006 בתירוצים האחרים.","וכיון שדנו כבר בענין תפילין, באים לברר עוד את הנושא לגופו, ושואלים: \u0003מאן\u0004 \u0005[מי הוא\u0006 החכם\u0005]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שדעתו ש\u0003שבת זמן תפילין? ר' עקיבא\u0004 הוא. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הנאמר בסיומה של פרשת \"קדש לי כל בכור\", הדנה במצוות פסח ובמצות תפילין: \u0003\"ושמרת את החקה הזאת למועדה מימים ימימה\"\u0004 (שמות יג, י), וכך דרשו: \u0003\"ימים\"\u0004 — לדייק ולהוציא: \u0003ולא לילות. \"מימים\"\u0004 — המ\"ם באה למעט, ללמדנו: \u0003ולא כל ימים,\u0004 משמע: \u0003פרט לשבתות וימים טובים\u0004 שאין מניחים בהם תפילין, אלו \u0003דברי ר' יוסי הגלילי.\u0004","\u0003ר' עקיבא אומר: לא נאמר חוקה זו אלא לענין פסח בלבד\u0004 ואין ענינה כלל לתפילין, וממילא מובן כי לדעת ר' עקיבא אין הגבלה להנחת תפילין בשבתות ובימים טובים.","ושואלים: \u0003ואלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הפסח והמילה מצות עשה\u0004 אבל אין בהן צד מצות לא תעשה, \u0003לימא\u0004 \u0005[האם לומר]\u0006 שדבר זה \u0003לא כר' עקיבא? דאי\u0004 \u0005[שאם]\u0006 תאמר כשיטת \u0003ר' עקיבא — כיון דמוקי לה\u0004 \u0005[שמעמיד אותו]\u0006 את הפסוק הזה בענין ה\u0003פסח, לאו נמי איכא\u0004 \u0005[גם כן יש],\u0006 וכדברי \u0003ר' אבין אמר ר' אילעאי.\u0004 ש\u0003אמר ר' אבין אמר ר' אילעאי: כל מקום שנאמר \"השמר\" \"פן\" ו\"אל\" — אינו אלא בלא תעשה,\u0004 שאף אלה ביטויים של שלילה הם. והרי אף לענין הפסח נאמר \"ושמרת את החוקה\", ושמירה משמעה מצות לא תעשה!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שההלכה שאין בפסח מצות לא תעשה, אף כ\u0003ר' עקיבא\u0004 היא, אלא יש לזכור כלל נוסף שאמנם \u0003\"השמר דלאו — לאו\",\u0004 שאם נאמרה לשון שמירה בציווי התורה שעניינו להימנע מלעשות דבר, הרי \"השמר\" זה משמעו כעין לא תעשה — להישמר ולא לעשות דבר זה. אולם \u0003\"השמר\"\u0004 של \u0003עשה — עשה,\u0004 שמשמעו תוספת הקפדה וזהירות בעשיית המצוה, ובפסח נאמרה לשון שמירה בתוספת לעשה.","ומקשים: ולעיקרו של דבר, \u0003ו\u0004כי \u0003סבר ר' עקיבא שבת זמן תפילין הוא?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' עקיבא אומר: יכול יניח אדם תפילין בשבתות וימים טובים — תלמוד לומר \"והיה לך לאות על ידך\u0004 ולזכרון בין עיניך למען תהיה תורת ה' בפיך כי ביד חזקה הוציאך ה' ממצרים\u0003\"\u0004 (שמות יג, ט), ומתי חל חיוב התפילין על \u0003מי שצריכין אות,\u0004 להוכיח ולאמת את יהדותם ובחירתם בימות החול, \u0003יצאו אלו\u0004 שבתות וימים טובים, \u0003שהן גופן אות\u0004 של בחירת ישראל, וזכר ליציאת מצרים, ואינן צריכין לאות נוסף, ואם כן ברור שר' עקיבא לא סבר ששבת זמן תפילין.","\u0003אלא האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הניעור בלילה, רצה\u0004 — \u0003חולץ\u0004 תפילין, \u0003רצה — מניח\u0004 ואינו חושש ל\"בל תוסיף\", אלו \u0003דברי ר' נתן. יונתן הקיטוני אומר: אין מניחין תפילין בלילה,\u0004 מכיון ש\u0003לילה ל\u0004שיטת \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 — הוא ר' נתן, \u0003זמן תפילין — שבת נמי\u0004 \u0005[גם כן]\u0006 \u0003זמן\u0004 הנחת \u0003תפלין,\u0004 שהרי אינו מקבל את המיעוט של \"מימים ימימה\" כשיטת ר' יוסי הגלילי.","ודוחים: זו אינה הוכחה, \u0003דילמא סבירא ליה\u0004 \u0005[שמא הוא סובר]\u0006 \u0003לילה זמן תפילין הוא, שבת — לאו\u0004 \u0005[לא]\u0006 \u0003זמן תפילין הוא. דהא שמעינן ליה\u0004 \u0005[שהרי שמענו אותו]\u0006 את \u0003ר' עקיבא\u0004 ש\u0003אמר: לילה זמן תפילין הוא,\u0004 שאינו ממעט \"מימים ימימה\", ובכל זאת \u0003שבת לאו\u0004 \u0005[לא]\u0006 \u0003זמן תפילין הוא,\u0004 שהרי אין צורך בהן לאות! ואף ר' נתן ייתכן שסובר כן.","\u0003אלא\u0004 יש לומר כי \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא\u0004 שסבור ששבת זמן תפילין הוא, \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מיכל בת כושי\u0004 (בת שאול המלך) \u0003היתה מנחת תפילין ולא מיחו בה חכמים\u0004 שהרשות בידה לעשות כך, וכן \u0003אשתו של יונה היתה עולה לרגל ולא מיחו בה חכמים.\u0004 מכיון ש\u0003לא מיחו בה חכמים — אלמא קסברי\u0004 \u0005[מכאן\u0006 ש\u0005סבורים הם]\u0006 חכמים אלה, כי \u0003מצות עשה שלא הזמן גרמא היא\u0004 וחייבים בה בכל עת ואף בלילות ובשבתות, ולפי הכלל המקובל כל מצות עשה שלא הזמן גרמא גם נשים חייבות בה.","ודוחים: \u0003ודילמא סבר לה\u0004 \u0005[ושמא סבור הוא]\u0006 אותו תנא"],["\u0003כר' יוסי\u0004 ש\u0003אמר: נשים סומכות רשות\u0004 שאף שמצות הסמיכה על הקרבנות נאמרה לגברים, בכל זאת מותר לנשים הרוצות בכך לסמוך אף הן. וכמו כן יכולות הנשים לקיים שאר מצוות שלא נתחייבו בהן.","\u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כן]\u0006 שהדבר הוא כשיטת ר' יוסי, \u0003אשתו של יונה היתה עולה לרגל ולא מיחו בה\u0004 בענין זה, \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 ש\u0003רגל לאו מצות עשה שהזמן גרמא הוא?\u0004 והלוא מצות עליה לרגל ודאי קבוע לה זמן מסוים! \u0003אלא קסבר\u0004 \u0005[סבור הוא]\u0006 שעלתה לרגל לא כחובה אלא כ\u0003רשות, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין תפילין \u0003רשות.\u0004 ולכן אין להוכיח מברייתא זו כלל לגבי זמן מצות תפילין עצמה.","\u0003אלא\u0004 מי הוא אותו תנא הסבור ששבת זמן תפילין? \u0003האי תנא היא\u0004 \u0005[תנא זה הוא]\u0006 בעל הלכה זו \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003המוצא תפילין, מכניסן זוג זוג. אחד האיש ואחד האשה, אחד חדשות ואחד ישנות,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אוסר בחדשות,\u0004 שייתכן ואינן אלא קמיע העשויה כתפילין, \u0003ומתיר בישנות\u0004 משום שבאלו יודעים אנו ודאי שהן תפילין ראויות וכשרות.","וכשנדקדק בתוספתא זו נמצא כי \u0003עד כאן לא\u0004 שמענו ש\u0003פליגי\u0004 \u0005[נחלקו]\u0006 ר' מאיר ור' יהודה \u0003אלא בחדשות וישנות, אבל באשה — לא פליגי\u0004 \u0005[נחלקו]\u0006 שמותר לה להביא את התפילין. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהתנא שניסח כך את המחלוקת סבור כי תפילין \u0003מצות עשה שלא הזמן גרמא הוא, וכל מצות עשה שאין הזמן גרמא נשים חייבות.\u0004 לפיכך יכולה אשה להניח תפילין אלו ולהכנס עמם לעיר.","ומנסים לדחות: \u0003ודילמא סבר לה\u0004 \u0005[ושמא סבור הוא\u0006 אותו תנא\u0005]\u0006 \u0003כר' יוסי,\u0004 ש\u0003אמר: נשים סומכות רשות\u0004 ואף כאן נשים מניחות תפילין רשות? ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 כי \u0003לא ר' מאיר סבר לה\u0004 \u0005[הוא]\u0006 \u0003כר' יוסי, ולא ר' יהודה סבר לה\u0004 \u0005[הוא]\u0006 \u0003כר' יוסי\u0004 כפי שנוכיח;","\u0003לא ר' מאיר סבר לה\u0004 \u0005[הוא]\u0006 \u0003כר' יוסי, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מעכבין את התינוקות מלתקוע\u0004 בשופר בראש השנה, ואף שיש מקצת איסור בתקיעה שאינה של מצוה, מכל מקום כיון שסופם להיות מחוייבים במצות תקיעה — אין מעכבים אותם לתקוע וללמוד. \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נדייק כי \u0003נשים — מעכבין\u0004 אותן מלתקוע. \u0003וסתם מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' מאיר,\u0004 משמע שר' מאיר סבור שאין אשה יכולה לקבל על עצמה כרשות קיום מצוה שהזמן גרמא.","\u0003וכן לא ר' יהודה סבר לה\u0004 \u0005[הוא]\u0006 \u0003כר' יוסי\u0004 שכן שנינו במדרש ההלכה תורת כהנים (ספרא) על הפסוק \u0003\"דבר אל בני ישראל... וסמך ידו\u0004 על ראש העולה\" (ויקרא א, ב וד) למדו מכאן ש\u0003בני ישראל סומכין ואין בנות ישראל סומכות. ר' יוסי ור' שמעון אומרים: נשים סומכות רשות.\u0004","\u0003וסתם סיפרא מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 כשיטת \u0003ר' יהודה\u0004 היא. ולמדנו מכאן שר' יהודה סבור שאין נשים סומכות רשות. וכיון שאין ר' מאיר ור' יהודה מקבלים את שיטת ר' יוסי שנשים יכולות לקיים מצוות שאין חובתם אלא כרשות בלבד, יש להבין שהתנא המוסר בשמם שאשה מביאה תפילין סבור כי מצות תפילין נוהגת תמיד, ולכן גם הנשים חייבות בה.","\u0003אמר ר' אלעזר: המוצא תכלת בשוק,\u0004 אם מצא את התכלת בצורת \u0003לשונות\u0004 שהן רצועות של צמר סרוק וצבוע — \u0003פסולות\u0004 לציצית, כי דרוש שתהא עשיית פתיל התכלת לשם מצות ציצית, ושמא נצבעו הלשונות לשם נתינתן בבגד אחר. אבל אם מצא \u0003חוטין — כשרין,\u0004 שמן הסתם לצורך ציצית נעשו.","ומקשים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003לשונות\u0004 שאסרנום, ש\u0003אמר:\u0004 משום שחוששים ואומרים שמא \u0003אדעתא\u0004 \u0005[על דעת]\u0006 לעשות מהן \u0003גלימא צבעינהו\u0004 \u0005[צבע אותן],\u0006 ואם כן \u0003חוטין נמי, נימא: אדעתא דגלימא טוינהו\u0004 \u0005[גם כן, נאמר: על דעת\u0006 לעשות מהם \u0005גלימא טוה אותם]\u0006 ומשיבים: מדובר כאן בחוטים \u0003שזורים,\u0004 שאין דרך להשתמש בהם לאריגה.","ומקשים: \u0003שזורים נמי, נימא: אדעתא דשיפתא דגלימא עייפינהו\u0004 \u0005[גם כן, נאמר: על דעת\u0006 להניחם \u0005בשפת הגלימה שזרם]\u0006 שיהיו כקישוט לה! ומשיבים: \u0003במופסקין,\u0004 שהיו חוטים שזורים אלה מופסקים וחתוכים חוטים חוטים קצרים כציצית. \u0003דכולי האי\u0004 \u0005[שכל כך]\u0006 \u0003ודאי לא טרחי אינשי\u0004 \u0005[טורחים אנשים]\u0006 בגדילי גלימה לעשותם כעין ציצית.","\u0003אמר רבא:\u0004 אין לסמוך על נימוק זה שאין אנשים טורחים בכך, וראיה לדבר: \u0003וכי אדם טורח לעשות קמיע כמין תפילין?\u0004 ובכל זאת חוששים אנו בדבר הדומה לתפילין שמא לא תפילין הן, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שמביא תפילין, \u0003בישנות. אבל בחדשות — פטור,\u0004 שיש לחשוש שמא עשה אדם קמיע כצורת תפילין. וכן צריך לחשוש גם לדברים אחרים, שאף שיש טורח גדול בעשייתם עושים אנשים כמותם.","\u0003אמר ר' זירא לאהבה בריה\u0004 \u0005[בנו]:\u0006 \u0003פוק תני להו\u0004 \u0005[צא שנה להם]\u0006 לחכמים שמצויים בבית המדרש, שכך לשונה של ברייתא: \u0003המוצא תכלת בשוק,\u0004 אם מצא \u0003לשונות — פסולין, חוטים מופסקים — כשרים. לפי שאין אדם טורח\u0004 עד כדי כך, ונמצא כי אמנם זה הוא טעמה של ההלכה.","\u0003אמר רבא: ומשום דתני לה\u0004 \u0005[ששנה אותה]\u0006 להלכה זו \u0003אהבה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' זירא כיפי תלא\u0004 \u0005[נזמים תלה]\u0006 \u0003לה?!\u0004 שהרי הקושי שהקשה רבא לא נתיישב בעצם לשון הברייתא. \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003במה דברים אמורים — בישנות, אבל בחדשות — פטור!\u0004 והיא הוכחה ברורה שיש לחשוש שמא טרח ועשה אדם דבר בדומה למכשירי מצוה.","\u0003אלא אמר רבא:\u0004 את הסתירה בין המקורות יש ליישב באופן זה: \u0003טרח ולא טרח\u0004 עד כדי כך — \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 יש סבורים שאדם טורח, כמשנה לענין תפילין. ואחרים סבורים שאינו טורח, כמו בענין תכלת.","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003המוצא תפילין — מכניסן זוג זוג, אחד האיש ואחד האשה.\u0004"],["\u0003אחד חדשות ואחד ישנות, דברי ר' מאיר. ר' יהודה אוסר בחדשות ומתיר בישנות. אלמא\u0004 \u0005[מכאן]\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003טרח איניש\u0004 \u0005[טורח אדם]\u0006 ועושה קמיע הנראה כעין תפילין, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר\u0005, סבור]:\u0006 אין אדם טורח בכך, ודבר הנראה כתפילין — ודאי תפילין הוא.","\u0003(שיצ\"י עצב\"י סימן).\u0004 ומוסיפים: \u0003והשתא דתני אבוה\u0004 \u0005[ועכשיו ששנה אביו]\u0006 של \u0003שמואל בר רב יצחק: אלו הן ישנות — כל שיש בהן רצועות ו\u0004הן \u0003מקושרות\u0004 בקשרים הקבועים בתפילין, \u0003חדשות — יש בהן רצועות ולא מקושרות.\u0004 משמע \u0003דכולי עלמא לא טרח איניש\u0004 \u0005[ש\u0006לדעת \u0005הכל אין אדם טורח]\u0006 לעשות קמיע הדומה לתפילין וכן גדיל הדומה לציצית, ומה שנחלקו בחדשות היה שכיון שאין התפילין מקושרות כראוי אינו יכול להניחן כפי שדרך להניחן בחול, ועשיית קשר קבוע בשבת אסורה מן התורה, ולכן אין להניח תפילין אלה, ונתקבלו דברי ר' זירא.","על דברי ר' יהודה להסברו של רב שמואל בר רב יצחק האוסר לקחת תפילין חדשות משום שאין בהן קשר, מקשים: ולשם מה יעשה קשר בתפילין? \u0003וליענבינהו מיענב\u0004 \u0005[ושיעשה עניבה]\u0006 בלבד, שאין איסור שבת בעשייתה, ויניחם כך בראשו ובזרועו! \u0003אמר רב חסדא: זאת אומרת, עניבה פסולה בתפילין\u0004 ויש צורך בקשירה ממש.","\u0003אביי אמר:\u0004 לא כך יש להבין, אלא \u0003ר' יהודה לטעמיה\u0004 \u0005[לשיטתו]\u0006 ש\u0003אמר: עניבה קשירה מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא,\u0004 ואיסור תורה לעשותה בשבת.","ומקשים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 הוא ש\u0003עניבה קשירה מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא, הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כך] —\u0006 היית אומר ש\u0003עניב להו\u0004 \u0005[עונב אותן]\u0006 את התפילין, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: קשר של תפילין\u0004 הקבוע בהן \u0003הלכה למשה מסיני הוא\u0004 שתהא צורתו כך, \u0003ואמר רב נחמן: ונוייהן\u0004 של הקשרים, הצד הנאה שנראית בו צורת אותיות, צריך לפנות \u0003לבר\u0004 \u0005[ל\u0006צד \u0005חוץ].\u0006 משמע שחייבים לעשות קשר בתפילין!","ודוחים: אף על פי כן אפשר שלא לעשות קשר קבוע אלא \u0003דעניב להו\u0004 \u0005[שעונב אותן]\u0006 \u0003כעין קשירה דידהו\u0004 \u0005[שלהם]\u0006 באותה צורה, אך לא על ידי קשר של קיימא.","\u0003אמר רב חסדא אמר רב: הלוקח\u0004 (קונה) כמות גדולה של \u0003תפילין ממי שאינו מומחה,\u0004 שאינו בדוק לנו אם יודע הוא לעשות תפילין כראוי — \u0003בודק שתים של יד ואחת של ראש, או שתים של ראש ואחת של יד\u0004 לדעת אם כשרים הם ויוכל לסמוך עליו, ועל ידי שלוש בדיקות נעשית חזקה שהכל כשר.","ושואלים: \u0003מה נפשך\u0004 \u0005[מה רצונך],\u0006 שהרי בכל אופן שתדון בדבר יקשה לך: כי \u0003אי מחד גברא קא זבין\u0004 \u0005[אם תאמר\u0006 שהקונה \u0005מאדם אחד קנה]\u0006 וגם המוכר קנאם מאחד, די לו \u0003לבדוק או שלש של יד או שלש של ראש,\u0004 שכלל הוא בידינו כי בשלוש פעמים הרי זו חזקה.","\u0003אי מתרי תלתא גברי זבין\u0004 \u0005[אם משנים שלושה אנשים קנה]\u0006 את התפילין, אם כן \u0003כל חד וחד ליבעי\u0004 \u0005[אחד ואחד\u0006 מן התפילין \u0005יצטרך]\u0006 \u0003בדיקה,\u0004 שהרי אין חזקה מזוג תפילין אחד לחבירו, ושמא ההוא משל אדם אחר. ומשיבים: \u0003לעולם\u0004 יש לפרש כי \u0003מחד גברא זבין\u0004 \u0005[מאדם אחד קנה],\u0006 אלא \u0003ובעינן דמיתמחי\u0004 \u0005[וצריכים שיתמחה]\u0006 שייחשב מומחה גם \u0003בשל יד ו\u0004גם \u0003בשל ראש.\u0004","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רבה בר שמואל: בתפילין בודק שלש של יד\u0004 ושלוש \u0003של ראש, מאי לאו\u0004 \u0005[האם לא]\u0006 צריך להבין את הדברים שעליו לבדוק \u0003או שלש של יד או שלש של ראש!\u0004 ודוחים \u0003לא,\u0004 אלא כך יש להבין: בודק \u0003שלש, מהן של יד מהן של ראש,\u0004 וכדברי רב חסדא בשם רב.","ומקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב כהנא: בתפילין בודק שתים של יד ושל ראש,\u0004 ובודאי אין זה כשיטת רב! ומסבירים \u0003הא מני\u0004 \u0005[\u0006הלכה \u0005זו\u0006 של רב כהנא, של \u0005מי היא]\u0006 כשיטת \u0003רבי היא,\u0004 ש\u0003אמר: בתרי זימני הוי\u0004 \u0005[בשתי פעמים הריהי]\u0006 \u0003חזקה,\u0004 שאף שרוב החכמים סבורים שחזקה נעשית על ידי חזרה שלוש פעמים, רבי סבור שדי בשתי פעמים לשם חזקה, ולכן אף בתפילין דיו שיבדוק שנים ולא יותר.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003רבי\u0004 היא, \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה ברייתא: \u0003וכן\u0004 צריך לבדוק \u0003בצבת\u0004 (הערימה) \u0003השני, וכן בצבת השלישי. ואי רבי — שלישי מי אית ליה\u0004 \u0005[האם יש לו],\u0006 האם דרושה לו בדיקת שלישי לשם חזקה? שהרי לשיטתו אף בצבתים לשם חזקה די בבדיקת שניים בלבד!","ומשיבים: \u0003מודה רבי בצבתים, דמתרי תלתא גברי זבין\u0004 \u0005[שמשניים שלושה אנשים קנה]\u0006 ומן הסתם לא אדם אחד עשה את כל ערימות התפילין הללו, וכל ערימה וערימה נעשתה בידי אחר, ואין לסמוך מערימה לחברתה. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו רביעי נמי\u0004 \u0005[גם כן],\u0006 \u0003ואפילו חמישי נמי\u0004 \u0005[גם כן],\u0006 שאם מרבים קנה הרי צריך לבדוק כל ערימה וערימה, ולא רק שלישית בלבד!","ועונים: \u0003אין הכי נמי\u0004 \u0005[אכן, כך גם כן]\u0006 יש להבין, וכן יש לעשות. \u0003והאי דקתני\u0004 \u0005[וזה ששנינו]\u0006 \u0003שלישי\u0004 ולא רביעי וחמישי, \u0003לאפוקי מחזקיה\u0004 \u0005[להוציא מחזקתו].\u0006 שגילה רבי שבמקרה זה אין לסמוך על שני בדיקות כשיטתו בחזקה, אלא יש לבדוק הכל, \u0003ולעולם אפילו רביעי וחמישי נמי\u0004 \u0005[גם כן]\u0006 צריך בדיקה.","שנינו במשנה: \u0003מצאן צבתים או כריכות\u0004 מחשיך עליהם ומביאן. והסבירו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003צבתים, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003כריכות? אמר רב יהודה אמר רב: הן הן צבתים, הן הן כריכות\u0004 שמשמען יותר מזוג אחד של תפילין. אלא \u0003צבתים — מסודרים בחבילה הרבה זוגות תפילין באופן שהם זווי זווי\u0004 \u0005[זוגות זוגות]\u0006 של ראש ושל יד, \u0003כריכות — דכריכן טובא\u0004 \u0005[שכרוכים הרבה]\u0006 יחד ללא סדר מסויים.","שנינו במשנה: \u0003מחשיך עליהן ומביאן.\u0004 ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יעשה כן? \u0003לעיילינהו\u0004 \u0005[שיכניסם]\u0006 \u0003זוג זוג! אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: לדידי מיפרשא ליה מיניה\u0004 \u0005[לי התפרש הדבר ממנו,\u0006 מאת\u0005]\u0006 \u0003אבא, כל\u0004 שהיו התפילין מועטות \u0003שאילו מכניסן זוג זוג וכלות קודם שקיעת החמה,\u0004 ראוי שיהא \u0003מכניסן זוג זוג. ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שהיו תפילין מרובות, שאם יכניס מהן זוג זוג ישארו מקצתן בחוץ גם אחרי שקיעת החמה, ובמילא יצטרך לשוב ליטלם לאחר שיחשיך, לכן מלכתחילה יהא \u0003מחשיך עליהן\u0004 על כולן \u0003ומביאן.\u0004","שנינו: \u0003ובסכנה מכסן והולך.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי\u0006 בברייתא \u0005שנינו]\u0006 אחרת: \u0003ובסכנה מוליכן פחות פחות מארבע אמות!\u0004 ומשיבים: \u0003אמר רב: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו במשנה שמוליכים את התפילין — \u0003מדובר בסכנת גוי,\u0004 שגזרו שלא להניח תפילין וירא שמא יראוהו השלטונות מטלטל תפילין. \u0003הא\u0004 \u0005[זה]\u0006 שאמרו בברייתא שמוליכים אותן — \u0003בסכנת לסטים,\u0004 שמפחד להחשיך אך אינו חושש לשאת תפילין עמו, ויכול לטלטלן."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: במאי אוקימתא למתניתין\u0004 \u0005[במה העמדת את משנתנו]\u0006 \u0003בסכנת גוי, אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של המשנה\u0005],\u0006 \u0003ר' שמעון אומר: נותנן לחבירו, וחבירו לחבירו. כל שכן דאוושא מילתא\u0004 \u0005[שרוגש הדבר]\u0006 והכל יודעים על כך, ואימת הגזירה עליהם!","ומשיבים: \u0003חסורי מיחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 המשנה, \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003במה דברים אמורים\u0004 שמכסה — \u0003בסכנת גוים, אבל בסכנת לסטים — מוליכן פחות פחות מארבע אמות,\u0004 ועל כך חלק ר' שמעון שלדעתו עדיף שיטלטלו רבים את התפילין.","במשנה שנינו, \u0003ר' שמעון אומר: נותנן לחבירו\u0004 ומחבירו לחבירו. ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[באיזה\u0006 עקרון \u0005נחלקו]?\u0006 \u0003מר\u0004 \u0005[חכם זה\u0006 התנא הראשון\u0005]\u0006 \u0003סבר: פחות מארבע אמות\u0004 על ידי אדם אחד \u0003עדיף, דאי אמרת\u0004 \u0005[שאם תאמר]\u0006 \u0003נותנן לחבירו וחבירו לחבירו — אוושא מילתא\u0004 \u0005[רוגש,\u0006 נתפרסם \u0005הדבר]\u0006 של חילול \u0003שבת\u0004 ויש בכך גנאי של ביטול מנוחת וקדושת היום.","\u0003ומר\u0004 \u0005[וחכם זה\u0006 ר' שמעון\u0005]\u0006 \u0003סבר: נותנן לחבירו עדיף, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 \u0003מוליכן פחות מארבע אמות — זימנין\u0004 \u0005[פעמים]\u0006 ש\u0003לא\u0004 יהא הדבר \u0003אדעתיה\u0004 \u0005[על דעתו]\u0006 וישכח, \u0003ו\u0004מתוך שלא ידקדק בשיעור \u0003אתי לאתויינהו\u0004 \u0005[יבוא להביאם]\u0006 \u0003ארבע אמות ברשות הרבים\u0004 בטעות, אבל כשמצויים רבים במקום וסמוכים זה לזה, לא יקרה כן.","שנינו: \u0003וכן בנו\u0004 קטן כך נוהגים בו. ותוהים: \u0003בנו, מאי בעי התם\u0004 \u0005[מה רוצה,\u0006 מה הוא עושה \u0005שם\u0006 בשדה\u0005],\u0006 שיש להביאו בדרך זו? \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה תנא\u0004 \u0005[שנינו]\u0006 מדובר \u0003בשילדתו אמו בשדה,\u0004 ויש להעבירו לעיר.","\u0003ומאי\u0004 \u0005[ומה\u0006 משמע\u0005]\u0006 מה הדקדוק בלשון \u0003אפילו הן מאה — דאף על גב דקשיא ליה ידא\u0004 \u0005[שאף על פי שקשה לו\u0006 מגע \u0005היד],\u0006 שאין זה נוח לתינוק בטלטולו מיד ליד, \u0003אפילו הכי\u0004 \u0005[כך],\u0006 \u0003הא עדיפא\u0004 \u0005[\u0006אופן \u0005זה עדיף]\u0006 מאשר טלטולו פחות פחות מארבע אמות על ידי אדם אחד.","שנינו במשנה כי \u0003ר' יהודה אומר: נותן אדם חבית\u0004 לחבירו ומחבירו לחבירו, ואפילו מעבירה מחוץ לתחום. ושואלים: \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו,\u0006 אינו סובר\u0005]\u0006 \u0003ר' יהודה הא\u0004 \u0005[זו]\u0006 ששנינו: \u0003הבהמה והכלים\u0004 דינם לענין תחומים \u0003כרגלי הבעלים\u0004 שבתחום, שמותר לבעליהם ללכת מותר גם להם!","\u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003לוי סבא\u0004 \u0005[הזקן]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003במערן\u0004 (בשופך אותם) את המים \u0003מחבית לחבית,\u0004 ונמצא שהחבית עצמה אינה מיטלטלת מחוץ לתחום אלא המים בלבד יוצאים מן התחום. \u0003ור' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 לענין זה, ש\u0003אמר: מים אין בהם ממש,\u0004 שאינם חשובים לעצמם מספיק כדי לאסור העברתם מחוץ לתחום.","וכפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 מחלוקת בענין זה: אם נתן אחד קמח לעיסה והשני מים, אמרו חכמים שאין מוליכים את הבצק אלא למקום ששני הבעלים רשאים ללכת אליו, ו\u0003ר' יהודה פוטר במים מפני שאין בהן ממש.\u0004","\u0003ומאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 בדברי חכמים במשנה \u0003לא תהלך זו,\u0004 שלכאורה מוסבים על החבית — \u0003לא יהלך מה שבזו יותר מרגלי הבעלים.\u0004","את ההסבר הזה דוחים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו,\u0006 את\u0005]\u0006 \u0003ר' יהודה\u0004 שמים אין בהם ממש \u0003היכא דבליען\u0004 \u0005[במקום ש\u0006הם \u0005מובלעים]\u0006 \u0003בעיסה\u0004 ואינם ניכרים לעצמם, ואולם \u0003היכא דאיתנהו בעינייהו, מי שמעת ליה\u0004 \u0005[היכן שמצויים בעינם, האם שמעת אותו]\u0006 אומר כן? \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי במים \u0003בקדירה אמר ר' יהודה\u0004 מים \u0003לא בטלי\u0004 \u0005[בטלים],\u0006 וכיצד יתכן כי כשהם \u0003בעינייהו בטלי\u0004 \u0005[בעינם יבטלו]?!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: מים ומלח — בטלין בעיסה,\u0004 שכן הם נבלעים בה ואינם ניכרים לעצמם. \u0003אבל אין בטלין בקדירה, מפני רוטבה,\u0004 שבקדירה יש רוטב או מרק וניכרים בו המים והמלח.","\u0003אלא אמר רבא\u0004 שיש לדחות את הפירוש הזה, ולומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003בחבית שקנתה שביתה\u0004 בכניסת השבת במקום מסויים משום שהיתה שייכת לאדם מסויים, \u0003ומים שלא קנו שביתה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 כגון מי מעין או נהר שאין להם שביתה במקום אחד. ש\u0003בטלה חבית לגבי מים,\u0004 שכיון שהחבית נועדה להחזקת המים — בטלה להם.","\u0003כדתנן\u0004 \u0005[שכיוצא בכך שנינו\u0006 במשנה\u0005]:\u0006 \u0003המוציא\u0004 בשבת מרשות לרשות את האדם \u0003החי במטה — פטור אף על\u0004 הוצאת \u0003המטה, מפני שהמטה טפילה לו.\u0004 והמוציא את האדם החי פטור מפני ש\"החי נושא את עצמו\" — שהוא מסייע מרצונו להקל את משאו מעל נושאיו, והוא כשותף להם.","וכן \u0003המוציא אוכלין פחות מכשיעור\u0004 שמתחייבים על הוצאתו בתוך כלי — \u0003פטור אף על\u0004 הוצאת \u0003הכלי, מפני שהכלי טפל לו.\u0004 ולפי אותו עקרון נאמר גם כן שהחבית בטלה למים שבתוכה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 מברייתא, \u0003ר' יהודה אומר: בשיירא\u0004 החונה בבקעה שאינה מוקפת, ורוצים בני השיירה לשתות, \u0003נותן אדם חבית לחבירו וחבירו לחבירו.\u0004 ונדייק מכאן \u0003בשיירא — אין\u0004 \u0005[כן]\u0006 מותר מפני הדוחק, \u0003שלא בשיירא — לא? אלא אמר רב יוסף: כי תנן נמי במתניתין\u0004 \u0005[כאשר שנינו גם כן במשנתנו]\u0006 \u0003בשיירא תנן\u0004 \u0005[שנינו],\u0006 ובשיירה הקילו חכמים, שהרי בני השיירה פעמים שאין להם מים ולהם צורך גדול במים ולא החמירו בדבר.","\u0003אביי אמר\u0004 שאין הכרח בהסבר זה אלא אפשר לומר כי \u0003בשיירא, אפילו חבית שקנתה שביתה ומים שקנו שביתה\u0004 — מותר לטלטל. ו\u0003שלא בשיירא — חבית שקנתה שביתה ומים שלא קנו שביתה,\u0004 אבל אם קנו המים שביתה — אסורים בטלטול.","\u0003רב אשי אמר: הכא\u0004 \u0005[כאן]\u0006 \u0003בחבית דהפקר עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ומים\u0004 של \u0003הפקר עסקינן\u0004 \u0005[עוסקים אנו]\u0006 וחבית ומים אלה לא קנו שביתה לעצמם, שהרי אינם שייכים לאיש. ושואלים: \u0003ומאן\u0004 \u0005[ומי הם]\u0006 ש\u0003אמרו לו\u0004 \"לא תהלך יותר מרגלי הבעלים\" — \u0003ר' יוחנן בן נורי היא,\u0004 והוא הולך לשיטתו ש\u0003אמר: חפצי הפקר קונין שביתה\u0004 במקום שהיו בו עם השבת ואסור להוציאם מתחומם. \u0003ומאי\u0004 \u0005[ומה]\u0006 דיוק הלשון \u0003\"לא תהלך זו יותר מרגלי הבעלים\"?\u0004 שהרי כפי שהסברנו אין להם בעלים, יש לבאר כך: \u0003לא יהלכו\u0004 חבית ומים \u0003אלו יותר מכלים שיש להם בעלים\u0004 ולא יצאו מתחומם כלל.","\u0003היה קורא בספר\u0004 העשוי כמגילה ויושב \u0003על האיסקופה\u0004 (מפתן) \u0003ונתגלגל הספר מידו\u0004 בחלקו, שצד אחד מן הספר הותרה גלילתו ויצא החוצה לרשות הרבים — \u0003גוללו\u0004 את הספר ומביאו \u0003אצלו.\u0004","\u0003היה קורא בראש הגג, ונתגלגל הספר מידו, עד שלא הגיע\u0004 הספר \u0003לעשרה טפחים\u0004 מן הקרקע — \u0003גוללו אצלו. משהגיע לעשרה טפחים\u0004 — משאירו כמות שהוא עד שתחשך, אבל \u0003הופכו על הכתב,\u0004 שלא יהא ספר קודש מונח בגלוי ובבזיון.","\u0003ר' יהודה אומר: אפילו אין\u0004 הספר \u0003מסולק\u0004 (מרוחק) \u0003מן הארץ אלא כמלא מחט — גוללו אצלו. ר' שמעון אומר: אפילו\u0004 היה הספר \u0003בארץ עצמו — גוללו אצלו, שאין לך דבר\u0004 שאיסורו רק \u0003משום שבות עומד בפני\u0004 קדושת \u0003כתבי הקודש.\u0004","על הפסקא הראשונה שבמשנה שואלים: \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003איסקופה היכי דמי\u0004 \u0005[מה היא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיתה זו \u0003איסקופא\u0004 שהיא \u0003רשות היחיד, וקמה\u0004 \u0005[ולפניה]\u0006 \u0003רשות הרבים, ו\u0004לפיכך יש להבין את דברי המשנה במובנם הכללי כי \u0003לא גזרינן דילמא נפיל\u0004 \u0005[גוזרים אנו שמא יפול]\u0006 כל הספר מידו \u0003ואתי לאתויי\u0004 \u0005[ויבוא להביאו],\u0006 ונמצא מכניס מרשות הרבים לרשות היחיד."]]};
